insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-corn-light-60w-e39', 'GSW-LEDCORNLIG', 'LED Corn Light 60W – E39 Mogul', 'commercial-lighting', 'led-retrofit-corn-light', 38, 48, false, 'Direct HID replacement corn lamp for post tops and wall packs — bypass the ballast and go LED.', 'Direct HID replacement corn lamp for post tops and wall packs — bypass the ballast and go LED.', '["60W | 8100 lm (250W HID equiv.)","5000K, 360° beam","100-277V, ballast bypass","cULus | 5-year warranty"]'::jsonb, 'in-stock', 'LED Corn Light 60W – E39 Mogul', 'Buy the LED Corn Light 60W – E39 Mogul wholesale in Canada. 60W | 8100 lm (250W HID equiv.) — cULus/DLC certified, flat $30 shipping.', 'The LED Corn Light 60W – E39 Mogul is an LED corn light that retrofits HID lamps — metal halide and high-pressure sodium — without replacing the fixture. 60W | 8100 lm (250W HID equiv.) on a mogul base that screws straight into the existing socket after a ballast bypass. Contractors retrofitting post tops, wall packs and high bays buy corn lights from GSW at wholesale pricing with same-day GTA pickup.', '[{"q":"Do I remove the ballast?","a":"Yes — corn lamps operate on line voltage and require a ballast bypass (direct wire). It is a straightforward change our customers do every day; if you are unsure, any licensed electrician can handle it quickly."},{"q":"What HID wattage does this replace?","a":"60W | 8100 lm (250W HID equiv.) typically replaces a 250W HID lamp at roughly half the energy draw and many times the rated life."}]'::jsonb, '/images/extras/c2.webp');
