insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('led-strip-fixture-4ft-40w', 'GSW-LEDSTRIPFI', 'LED Linear Strip Fixture 4ft – 40W', 'commercial-lighting', 'led-linear-strip-fixture', 46, 58, false, '4-foot LED striplight for utility areas, retail back rooms and continuous rows.', '4-foot LED striplight for utility areas, retail back rooms and continuous rows.', '["40W | 5200 lm","4000K/5000K","120-277V, 0-10V dimmable","DLC listed | cULus"]'::jsonb, 'in-stock', 'LED Linear Strip Fixture 4ft – 40W', 'Buy the LED Linear Strip Fixture 4ft – 40W wholesale in Canada. 40W | 5200 lm — cULus/DLC certified, flat $30 shipping.', 'The LED Linear Strip Fixture 4ft – 40W is a commercial LED striplight for utility areas, retail back rooms and continuous-row installations. 40W | 5200 lm in a slim housing that links end-to-end for clean, continuous runs. GTA contractors buy striplights wholesale from GSW because we stock 4ft and 8ft lengths in quantity and deliver to the job site on schedule.', '[{"q":"Can I link multiple fixtures in a row?","a":"Yes — striplights link end-to-end with connector whips, and rows can be fed from a single junction. We can plan the feed points with you if you share the room dimensions."},{"q":"4ft or 8ft — which is more economical?","a":"8ft fixtures use fewer housings and junction boxes per foot of run, which usually wins on installed cost for long rows. 4ft units are easier to handle and fit in chopped-up spaces."}]'::jsonb, '/images/extras/wkiaivjqmycfsa2taaemtkibiwe630.webp');
