insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('canolight-cl-ll1a-pc-cover-canolight', 'CANOLIGHT-LL1APCCOVERCANOLIGHT', 'CL-LL1A-PC Cover - Canolight', 'residential-lighting', 'led-strip-light', 0, null, false, 'LL1 Up & Down LED Linear Light Accessory - PC Cover 25ft/roll Dimensions available in catalogue sheet', 'LL1 Up & Down LED Linear Light Accessory - PC Cover 25ft/roll Dimensions available in catalogue sheet', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'CL-LL1A-PC Cover - Canolight Canada', 'Buy the CL-LL1A-PC Cover - Canolight wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The CL-LL1A-PC Cover - Canolight is a professional-grade LED strip light system for coves, toe-kicks, shelving and accent runs. Genuine manufacturer product on a flexible tape that cuts to length and sticks in place, with aluminum channel options for a finished architectural look. As a lighting distributor in Mississauga, GSW stocks tape, drivers and channels together so your whole run comes from one supplier.', '[{"q":"12V or 24V — which should I use?","a":"We recommend 24V for runs longer than about 5 metres to avoid voltage drop and dimming at the far end. Both are in stock; tell us the run length and we will size the driver."},{"q":"Is the strip dimmable?","a":"Yes, with a compatible dimmable driver. We can supply the matching driver and dimmer so the whole circuit dims smoothly from one switch."}]'::jsonb, '/images/products/brand-canolight-cl-ll1a-pc-cover-canolight.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('canolight-cl-cont-step-es32-v-canolight', 'CANOLIGHT-CONTSTEPES32VCANOLIGHT', 'CL-CONT-STEP-ES32-V - Canolight', 'residential-lighting', 'led-outdoor-garden-light', 0, null, false, '32 Step Controller 5-24V DC Input 32 Channels Compatible with normal strip lights 1A / channel Sensor Distance 3m Sensor Angle 30 ( 10 ) IP20 &nbsp; Includin', '32 Step Controller 5-24V DC Input 32 Channels Compatible with normal strip lights 1A / channel Sensor Distance 3m Sensor Angle 30 ( 10 ) IP20 &nbsp; Including 1pc of Daylight Sensor, 2pc of 1.2m Sensor Heads, 2pcs sof 5m Sensor Extension Cord &nbsp;', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'CL-CONT-STEP-ES32-V - Canolight', 'Buy the CL-CONT-STEP-ES32-V - Canolight wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The CL-CONT-STEP-ES32-V - Canolight is a weather-rated LED garden light built to make Ontario landscapes look their best year-round. Genuine manufacturer product in a durable housing that shrugs off rain, snow and hose spray. Landscape contractors and DIY homeowners alike buy garden lighting from GSW’s Mississauga store for the combination of wholesale pricing and in-stock depth.', '[{"q":"Low voltage or line voltage?","a":"Most landscape fixtures run on 12V AC/DC from a transformer, which is safer to bury and easier to install. Line-voltage models are available for permanent hardwired installs — call to confirm."},{"q":"Will these survive a Canadian winter?","a":"Yes — these fixtures are IP65-rated with cold-rated LEDs and drivers, tested well below typical Ontario winter temperatures."}]'::jsonb, '/images/products/brand-canolight-cl-cont-step-es32-v-canolight.webp');
