insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('canolight-cl-ll1a-y-corner-canolight', 'CANOLIGHT-LL1AYCORNERCANOLIGHT', 'CL-LL1A-Y Corner - Canolight', 'commercial-lighting', 'led-retrofit-corn-light', 0, null, false, 'LL1 Up & Down LED Linear Light Accessory - Y Corner Dimensions available in catalogue sheet', 'LL1 Up & Down LED Linear Light Accessory - Y Corner Dimensions available in catalogue sheet', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'CL-LL1A-Y Corner - Canolight Canada', 'Buy the CL-LL1A-Y Corner - Canolight wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The CL-LL1A-Y Corner - Canolight is an LED corn light that retrofits HID lamps — metal halide and high-pressure sodium — without replacing the fixture. Genuine manufacturer product on a mogul base that screws straight into the existing socket after a ballast bypass. Contractors retrofitting post tops, wall packs and high bays buy corn lights from GSW at wholesale pricing with same-day GTA pickup.', '[{"q":"Do I remove the ballast?","a":"Yes — corn lamps operate on line voltage and require a ballast bypass (direct wire). It is a straightforward change our customers do every day; if you are unsure, any licensed electrician can handle it quickly."},{"q":"What HID wattage does this replace?","a":"Genuine manufacturer product typically replaces a 400W HID lamp at roughly half the energy draw and many times the rated life."}]'::jsonb, '/images/products/brand-canolight-cl-ll1a-y-corner-canolight.webp');
