insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('canolight-cl-ll1a-v120-corner-canolight', 'CANOLIGHT-LL1AV120CORNERCANOLIGHT', 'CL-LL1A-V120 Corner - Canolight', 'commercial-lighting', 'led-retrofit-corn-light', 0, null, false, 'LL1 Up & Down LED Linear Light Accessory - 120 Connector Dimensions available in catalogue sheet', 'LL1 Up & Down LED Linear Light Accessory - 120 Connector Dimensions available in catalogue sheet', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'CL-LL1A-V120 Corner - Canolight', 'Buy the CL-LL1A-V120 Corner - Canolight wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The CL-LL1A-V120 Corner - Canolight is an LED corn light that retrofits HID lamps — metal halide and high-pressure sodium — without replacing the fixture. Genuine manufacturer product on a mogul base that screws straight into the existing socket after a ballast bypass. Contractors retrofitting post tops, wall packs and high bays buy corn lights from GSW at wholesale pricing with same-day GTA pickup.', '[{"q":"Do I remove the ballast?","a":"Yes — corn lamps operate on line voltage and require a ballast bypass (direct wire). It is a straightforward change our customers do every day; if you are unsure, any licensed electrician can handle it quickly."},{"q":"What HID wattage does this replace?","a":"Genuine manufacturer product typically replaces a 400W HID lamp at roughly half the energy draw and many times the rated life."}]'::jsonb, '/images/products/brand-canolight-cl-ll1a-v120-corner-canolight.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-6-8243-commercial-downlight-8211-5way-cct-adj', 'VOTATEC-8243COMMERCIALDOWNLIGHT82115WAYC', '6 Commercial Downlight 5Way CCT Adj', 'residential-lighting', 'led-recessed-down-light', 0, null, false, '6" commercial LED downlight, 12W to 30W selectable, 125Lm/W, 5-CCT (2700K to 5000K), AC120-347V, wet-location rated, CRI >90. Request a quote.', '6" commercial LED downlight, 12W to 30W selectable, 125Lm/W, 5-CCT (2700K to 5000K), AC120-347V, wet-location rated, CRI >90. Request a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '6 Commercial Downlight 5Way CCT Adj', 'Buy the 6 Commercial Downlight 5Way CCT Adj wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The 6 Commercial Downlight 5Way CCT Adj is a commercial-grade recessed LED downlight with the colour quality and glare control specifiers ask for. Genuine manufacturer product, with high CRI that makes finishes and merchandise look right. Toronto-area electrical contractors source commercial downlights from GSW because we stock project quantities and match spec sheets item for item.', '[{"q":"What does 90+ CRI mean for my project?","a":"CRI measures colour accuracy. A 90+ CRI downlight renders materials and skin tones faithfully — the standard for retail, galleries and healthcare, and a noticeable upgrade over 80 CRI economy fixtures."},{"q":"Can these dim on my existing controls?","a":"We stock versions dimmable by TRIAC, ELV and 0-10V. Send us the switch or control schedule and we will match the exact driver variant."}]'::jsonb, '/images/products/brand-votatec-6-8243-commercial-downlight-8211-5way-cct-adj.webp');
