insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-motion-security-solar-light', 'VOTATEC-SECURITYSOLARLIGHT', 'Motion Security Solar Light', 'residential-lighting', 'led-motion-sensor-light', 0, null, false, 'LED motion security light, 24W, 2200Lm, 5-CCT (2700K to 5000K), 120V, PIR 240 sensor, 65ft range, IP54. Garage and side door. Get a quote.', 'LED motion security light, 24W, 2200Lm, 5-CCT (2700K to 5000K), 120V, PIR 240 sensor, 65ft range, IP54. Garage and side door. Get a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Motion Security Solar Light Canada', 'Buy the Motion Security Solar Light wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Motion Security Solar Light is a motion-activated LED security light that switches on when it matters and stays off when it does not. Genuine manufacturer product with adjustable sensing so you cover the entry, driveway or yard without nuisance trips. GSW is an electrical wholesaler supplying motion sensor lighting across the GTA with contractor pricing and counter pickup in Mississauga.', '[{"q":"Can I adjust the sensitivity and timer?","a":"Yes — the PIR range, dwell time and lux threshold are all field-adjustable, so the light only triggers at night and only when you want it to."},{"q":"Is hardwiring required?","a":"These are hardwired 120V fixtures. For areas without a nearby box, ask us about solar or plug-in alternatives when you call."}]'::jsonb, '/images/products/brand-votatec-motion-security-solar-light.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-4ft-architectural-linear-fixture-8211-4cct-038-watt-adjustab', 'VOTATEC-ARCHITECTURALLINEARFIXTURE82114C', '4ft Architectural Linear Fixture 4CCT & Watt Adjustable', 'residential-lighting', 'led-gimbals', 0, null, false, '4ft architectural linear LED, 30W/40W/50W selectable, 130Lm/W, 4-CCT (3000K to 5000K), AC120-347V, linkable. Office and retail. Get a quote.', '4ft architectural linear LED, 30W/40W/50W selectable, 130Lm/W, 4-CCT (3000K to 5000K), AC120-347V, linkable. Office and retail. Get a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '4ft Architectural Linear Fixture 4…', 'Buy the 4ft Architectural Linear Fixture 4CCT & Watt Adjustable wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The 4ft Architectural Linear Fixture 4CCT & Watt Adjustable is an adjustable LED gimbal downlight that lets you aim light exactly where the design calls for it — artwork, feature walls, kitchen islands and sloped ceilings. Genuine manufacturer product in a compact trim that disappears into the ceiling. GSW stocks 3-inch and 4-inch gimbals at our Mississauga electrical supply store for same-day contractor pickup, with flat $30 shipping across Canada.', '[{"q":"How much can a gimbal tilt?","a":"Most of our gimbals tilt 30–35 degrees and swivel a full 360 degrees, so one fixture position can serve multiple aiming points without moving the ceiling box."},{"q":"Can I use gimbals in an insulated ceiling?","a":"Yes. These fixtures are IC-rated for direct contact with insulation, provided the fixture is installed according to the listing."}]'::jsonb, '/images/products/brand-votatec-4ft-architectural-linear-fixture-8211-4cct-038-watt-adjustab.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-premium-dimmer-switch', 'VOTATEC-DIMMERSWITCH', 'Premium Dimmer Switch', 'commercial-lighting', 'device', 0, null, false, 'The Premium Dimmer Switch (VO-DIM-P-W200) is an LED compatible dimmer switch that wires in without a neutral, in single-pole or 3-way circuits. Digital circuit', 'The Premium Dimmer Switch (VO-DIM-P-W200) is an LED compatible dimmer switch that wires in without a neutral, in single-pole or 3-way circuits. Digital circuit dimming carries 3-200W of dimmable LED, 15-600W incandescent, or 3-300W CFL. A vertical slider sets the level. A recessed adjuster wheel&hellip;', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Premium Dimmer Switch Canada', 'Buy the Premium Dimmer Switch wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Premium Dimmer Switch is a commercial-grade electrical device rated for the demands of everyday contractor use — not the big-box residential line. Genuine manufacturer product with back and side wiring for fast installs. GSW stocks receptacles, switches, GFCI and dimmers at the Mississauga counter in contractor case quantities.', '[{"q":"Commercial grade vs residential grade — does it matter?","a":"Yes. Commercial-grade devices use thicker contacts and bodies rated for heavier use — they survive ten-tenant condos and retail traffic where residential devices fail early. The price difference is small; the callbacks are not."},{"q":"Do you stock tamper-resistant and GFCI devices?","a":"Yes — TR receptacles are code-required in most residential locations, and we stock GFCI in 15A and 20A, plus AFCI breakers to match. Everything to pass inspection in one order."}]'::jsonb, '/images/products/brand-votatec-premium-dimmer-switch.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-back-lit-panel-5way-cct-watt-adjustable-sensor-8211-40w-1x4f', 'VOTATEC-LITPANEL5WAYCCTWATTADJUSTABLESEN', 'Back-Lit Panel 5WAY CCT/WATT Adjustable Sensor 40W-1x4ft', 'residential-lighting', 'led-gimbals', 0, null, false, 'Power:40WInput Voltage: AC100-277VPower Factor: >0.9CCT: 4000K/5000KBeam Angle: 140', 'Power:40WInput Voltage: AC100-277VPower Factor: >0.9CCT: 4000K/5000KBeam Angle: 140', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Back-Lit Panel 5WAY CCT/WATT Adjus…', 'Buy the Back-Lit Panel 5WAY CCT/WATT Adjustable Sensor 40W-1x4ft wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Back-Lit Panel 5WAY CCT/WATT Adjustable Sensor 40W-1x4ft is an adjustable LED gimbal downlight that lets you aim light exactly where the design calls for it — artwork, feature walls, kitchen islands and sloped ceilings. Genuine manufacturer product in a compact trim that disappears into the ceiling. GSW stocks 3-inch and 4-inch gimbals at our Mississauga electrical supply store for same-day contractor pickup, with flat $30 shipping across Canada.', '[{"q":"How much can a gimbal tilt?","a":"Most of our gimbals tilt 30–35 degrees and swivel a full 360 degrees, so one fixture position can serve multiple aiming points without moving the ceiling box."},{"q":"Can I use gimbals in an insulated ceiling?","a":"Yes. These fixtures are IC-rated for direct contact with insulation, provided the fixture is installed according to the listing."}]'::jsonb, '/images/products/brand-votatec-back-lit-panel-5way-cct-watt-adjustable-sensor-8211-40w-1x4f.webp');
