insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-2ft-vapor-tight-8211-cct-038-power-adjustable', 'VOTATEC-VAPORTIGHT8211CCT038POWERADJUSTA', '2ft Vapor Tight CCT & Power Adjustable', 'industrial-lighting', 'led-vapor-tight-fixture', 0, null, false, 'Linkable 2ft vapor tight LED, CCT and power-adjustable, 2175Lm. Connect up to 8 units. IP-rated for garages, warehouses, and wet-location installations.', 'Linkable 2ft vapor tight LED, CCT and power-adjustable, 2175Lm. Connect up to 8 units. IP-rated for garages, warehouses, and wet-location installations.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '2ft Vapor Tight CCT & Power Adjust…', 'Buy the 2ft Vapor Tight CCT & Power Adjustable wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The 2ft Vapor Tight CCT & Power Adjustable is a sealed, gasketed LED vapor tight fixture for parking garages, car washes, tunnels and cold storage. Genuine manufacturer product behind an impact-resistant lens that keeps out moisture, dust and corrosion. Contractors building parkades and wash bays across Canada buy vapor tight lighting from GSW for the IP65/IP66 rating depth and fast flat-rate shipping.', '[{"q":"IP65 vs IP66 — what is the difference?","a":"Both are dust-tight and hose-proof; IP66 adds protection against powerful jets, which matters in wash-down and pressure-wash environments. We stock both — tell us the cleaning regime and we will spec it."},{"q":"Does it handle cold temperatures?","a":"Yes — LED vapor tights with quality drivers start reliably well below freezing, making them the standard for unheated parkades and cold storage across Canada."}]'::jsonb, '/images/products/brand-votatec-2ft-vapor-tight-8211-cct-038-power-adjustable.webp');
