insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-360-pir-occupancy-sensor', 'VOTATEC-PIROCCUPANCYSENSOR', '360 PIR Occupancy Sensor', 'residential-lighting', 'led-motion-sensor-light', 0, null, false, '360 PIR Occupancy Sensor |', '360 PIR Occupancy Sensor |', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '360 PIR Occupancy Sensor Canada', 'Buy the 360 PIR Occupancy Sensor wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The 360 PIR Occupancy Sensor is a motion-activated LED security light that switches on when it matters and stays off when it does not. Genuine manufacturer product with adjustable sensing so you cover the entry, driveway or yard without nuisance trips. GSW is an electrical wholesaler supplying motion sensor lighting across the GTA with contractor pricing and counter pickup in Mississauga.', '[{"q":"Can I adjust the sensitivity and timer?","a":"Yes — the PIR range, dwell time and lux threshold are all field-adjustable, so the light only triggers at night and only when you want it to."},{"q":"Is hardwiring required?","a":"These are hardwired 120V fixtures. For areas without a nearby box, ask us about solar or plug-in alternatives when you call."}]'::jsonb, '/images/products/brand-votatec-360-pir-occupancy-sensor.webp');
