insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-led-area-light-8211-cct-038-power-adjustable-150w', 'VOTATEC-AREALIGHT8211CCT038POWERADJUSTAB', 'LED Area Light CCT & Power Adjustable -150W', 'commercial-lighting', 'led-outdoor-shoebox-light', 0, null, false, 'LED area light, 80W/100W/120W/150W selectable, 12800-24000Lm, 3000K/4000K/5000K, AC120-347V. Pole, square, or wall mount. Parking lots. Request a quote.', 'LED area light, 80W/100W/120W/150W selectable, 12800-24000Lm, 3000K/4000K/5000K, AC120-347V. Pole, square, or wall mount. Parking lots. Request a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'LED Area Light CCT & Power Adjusta…', 'Buy the LED Area Light CCT & Power Adjustable -150W wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The LED Area Light CCT & Power Adjustable -150W is an LED shoebox area light for parking lots, roadways and big-box retail sites. Genuine manufacturer product with field-selectable optics and an included photocell for dusk-to-dawn operation. Canadian contractors buy shoebox lighting wholesale from GSW — DLC-listed product, 10kV surge protection options, and flat-rate shipping to any job site in the country.', '[{"q":"Pole mount or wall mount?","a":"Shoeboxes typically mount on poles with a slip-fitter (2-3/8 inch tenon) — we stock adapters for wall and trunnion mounting too. Tell us the pole schedule and we will configure the order."},{"q":"What optic do I need?","a":"Type III throws light forward along roadways and aisles; Type IV is symmetrical for open lots; Type V is a broad square for centred poles. We can help choose from the site plan or photometric."}]'::jsonb, '/images/products/brand-votatec-led-area-light-8211-cct-038-power-adjustable-150w.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-0-10v-dimmer-switch-8211-1200w', 'VOTATEC-10VDIMMERSWITCH82111200W', '0-10V Dimmer Switch 1200W', 'commercial-lighting', 'device', 0, null, false, 'premium dimmer switch |', 'premium dimmer switch |', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '0-10V Dimmer Switch 1200W Canada', 'Buy the 0-10V Dimmer Switch 1200W wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The 0-10V Dimmer Switch 1200W is a commercial-grade electrical device rated for the demands of everyday contractor use — not the big-box residential line. Genuine manufacturer product with back and side wiring for fast installs. GSW stocks receptacles, switches, GFCI and dimmers at the Mississauga counter in contractor case quantities.', '[{"q":"Commercial grade vs residential grade — does it matter?","a":"Yes. Commercial-grade devices use thicker contacts and bodies rated for heavier use — they survive ten-tenant condos and retail traffic where residential devices fail early. The price difference is small; the callbacks are not."},{"q":"Do you stock tamper-resistant and GFCI devices?","a":"Yes — TR receptacles are code-required in most residential locations, and we stock GFCI in 15A and 20A, plus AFCI breakers to match. Everything to pass inspection in one order."}]'::jsonb, '/images/products/brand-votatec-0-10v-dimmer-switch-8211-1200w.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-led-area-light-8211-cct-038-power-adjustable-8211-300w', 'VOTATEC-AREALIGHT8211CCT038POWERADJUSTAB-2', 'LED Area Light CCT & Power Adjustable 300W', 'commercial-lighting', 'led-outdoor-shoebox-light', 0, null, false, 'LED area light, 150W/200W/240W/300W selectable, 24000-48000Lm, CCT switchable, AC120-347V. Pole and wall mount. Lots, yards, campuses. Get a quote.', 'LED area light, 150W/200W/240W/300W selectable, 24000-48000Lm, CCT switchable, AC120-347V. Pole and wall mount. Lots, yards, campuses. Get a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'LED Area Light CCT & Power Adjusta…', 'Buy the LED Area Light CCT & Power Adjustable 300W wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The LED Area Light CCT & Power Adjustable 300W is an LED shoebox area light for parking lots, roadways and big-box retail sites. Genuine manufacturer product with field-selectable optics and an included photocell for dusk-to-dawn operation. Canadian contractors buy shoebox lighting wholesale from GSW — DLC-listed product, 10kV surge protection options, and flat-rate shipping to any job site in the country.', '[{"q":"Pole mount or wall mount?","a":"Shoeboxes typically mount on poles with a slip-fitter (2-3/8 inch tenon) — we stock adapters for wall and trunnion mounting too. Tell us the pole schedule and we will configure the order."},{"q":"What optic do I need?","a":"Type III throws light forward along roadways and aisles; Type IV is symmetrical for open lots; Type V is a broad square for centred poles. We can help choose from the site plan or photometric."}]'::jsonb, '/images/products/brand-votatec-led-area-light-8211-cct-038-power-adjustable-8211-300w.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-led-area-light-8211-cct-038-power-adjustable-8211-500w', 'VOTATEC-AREALIGHT8211CCT038POWERADJUSTAB-3', 'LED Area Light CCT & Power Adjustable 500W', 'commercial-lighting', 'led-outdoor-shoebox-light', 0, null, false, 'Heavy-duty LED area light, 240W/300W/400W/500W selectable, 38400-80000Lm, CCT switchable, AC120-347V. Large lots and industrial sites. Request a quote.', 'Heavy-duty LED area light, 240W/300W/400W/500W selectable, 38400-80000Lm, CCT switchable, AC120-347V. Large lots and industrial sites. Request a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'LED Area Light CCT & Power Adjusta…', 'Buy the LED Area Light CCT & Power Adjustable 500W wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The LED Area Light CCT & Power Adjustable 500W is an LED shoebox area light for parking lots, roadways and big-box retail sites. Genuine manufacturer product with field-selectable optics and an included photocell for dusk-to-dawn operation. Canadian contractors buy shoebox lighting wholesale from GSW — DLC-listed product, 10kV surge protection options, and flat-rate shipping to any job site in the country.', '[{"q":"Pole mount or wall mount?","a":"Shoeboxes typically mount on poles with a slip-fitter (2-3/8 inch tenon) — we stock adapters for wall and trunnion mounting too. Tell us the pole schedule and we will configure the order."},{"q":"What optic do I need?","a":"Type III throws light forward along roadways and aisles; Type IV is symmetrical for open lots; Type V is a broad square for centred poles. We can help choose from the site plan or photometric."}]'::jsonb, '/images/products/brand-votatec-led-area-light-8211-cct-038-power-adjustable-8211-500w.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-6-8243-recessed-panel-night-light', 'VOTATEC-8243RECESSEDPANELNIGHTLIGHT', '6 Recessed Panel Night Light', 'residential-lighting', 'led-recessed-down-light', 0, null, false, '6" recessed LED panel with built-in night light. Two fixtures in one for hallways, washrooms, and patient rooms. Wholesale to Canadian contractors.', '6" recessed LED panel with built-in night light. Two fixtures in one for hallways, washrooms, and patient rooms. Wholesale to Canadian contractors.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '6 Recessed Panel Night Light Canada', 'Buy the 6 Recessed Panel Night Light wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The 6 Recessed Panel Night Light is a commercial-grade recessed LED downlight with the colour quality and glare control specifiers ask for. Genuine manufacturer product, with high CRI that makes finishes and merchandise look right. Toronto-area electrical contractors source commercial downlights from GSW because we stock project quantities and match spec sheets item for item.', '[{"q":"What does 90+ CRI mean for my project?","a":"CRI measures colour accuracy. A 90+ CRI downlight renders materials and skin tones faithfully — the standard for retail, galleries and healthcare, and a noticeable upgrade over 80 CRI economy fixtures."},{"q":"Can these dim on my existing controls?","a":"We stock versions dimmable by TRIAC, ELV and 0-10V. Send us the switch or control schedule and we will match the exact driver variant."}]'::jsonb, '/images/products/brand-votatec-6-8243-recessed-panel-night-light.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-wifi-smart-dimmer-switch', 'VOTATEC-SMARTDIMMERSWITCH', 'WIFI Smart Dimmer Switch', 'commercial-lighting', 'device', 0, null, false, 'WiFi smart dimmer switch for LED loads. App and voice control, schedule-ready. Wholesale lighting controls shipped across Canada by Votatec.', 'WiFi smart dimmer switch for LED loads. App and voice control, schedule-ready. Wholesale lighting controls shipped across Canada by Votatec.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'WIFI Smart Dimmer Switch Canada', 'Buy the WIFI Smart Dimmer Switch wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The WIFI Smart Dimmer Switch is a commercial-grade electrical device rated for the demands of everyday contractor use — not the big-box residential line. Genuine manufacturer product with back and side wiring for fast installs. GSW stocks receptacles, switches, GFCI and dimmers at the Mississauga counter in contractor case quantities.', '[{"q":"Commercial grade vs residential grade — does it matter?","a":"Yes. Commercial-grade devices use thicker contacts and bodies rated for heavier use — they survive ten-tenant condos and retail traffic where residential devices fail early. The price difference is small; the callbacks are not."},{"q":"Do you stock tamper-resistant and GFCI devices?","a":"Yes — TR receptacles are code-required in most residential locations, and we stock GFCI in 15A and 20A, plus AFCI breakers to match. Everything to pass inspection in one order."}]'::jsonb, '/images/products/brand-votatec-wifi-smart-dimmer-switch.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-4ft-t8-glass-led-tube-with-plastic-coating-5way-cct-adjustab', 'VOTATEC-T8GLASSLEDTUBEWITHPLASTICCOATING', '4FT T8 Glass LED Tube with Plastic Coating- 5Way CCT Adjustable', 'residential-lighting', 'led-gimbals', 0, null, false, '4ft T8 LED tube. Type A ballast-compatible, 15W, 2400 lm, 4000K/5000K, plastic-coated glass for safer installs. Wholesale tubes across Canada.', '4ft T8 LED tube. Type A ballast-compatible, 15W, 2400 lm, 4000K/5000K, plastic-coated glass for safer installs. Wholesale tubes across Canada.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '4FT T8 Glass LED Tube with Plastic…', 'Buy the 4FT T8 Glass LED Tube with Plastic Coating- 5Way CCT Adjustable wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shi…', 'The 4FT T8 Glass LED Tube with Plastic Coating- 5Way CCT Adjustable is an adjustable LED gimbal downlight that lets you aim light exactly where the design calls for it — artwork, feature walls, kitchen islands and sloped ceilings. Genuine manufacturer product in a compact trim that disappears into the ceiling. GSW stocks 3-inch and 4-inch gimbals at our Mississauga electrical supply store for same-day contractor pickup, with flat $30 shipping across Canada.', '[{"q":"How much can a gimbal tilt?","a":"Most of our gimbals tilt 30–35 degrees and swivel a full 360 degrees, so one fixture position can serve multiple aiming points without moving the ceiling box."},{"q":"Can I use gimbals in an insulated ceiling?","a":"Yes. These fixtures are IC-rated for direct contact with insulation, provided the fixture is installed according to the listing."}]'::jsonb, '/images/products/brand-votatec-4ft-t8-glass-led-tube-with-plastic-coating-5way-cct-adjustab.webp');
