insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-transformer-for-landscape-lighting-8211-88w', 'VOTATEC-FORLANDSCAPELIGHTING821188W', 'Transformer for Landscape Lighting 88W', 'residential-lighting', 'led-outdoor-garden-light', 0, null, false, 'Landscape lighting transformer, 88W, 120V to 12VAC, 7.3A, photocell with 4 modes + 4/6/8hr timer, weatherproof. UL certified. Request a quote.', 'Landscape lighting transformer, 88W, 120V to 12VAC, 7.3A, photocell with 4 modes + 4/6/8hr timer, weatherproof. UL certified. Request a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Transformer for Landscape Lighting…', 'Buy the Transformer for Landscape Lighting 88W wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Transformer for Landscape Lighting 88W is a weather-rated LED garden light built to make Ontario landscapes look their best year-round. Genuine manufacturer product in a durable housing that shrugs off rain, snow and hose spray. Landscape contractors and DIY homeowners alike buy garden lighting from GSW’s Mississauga store for the combination of wholesale pricing and in-stock depth.', '[{"q":"Low voltage or line voltage?","a":"Most landscape fixtures run on 12V AC/DC from a transformer, which is safer to bury and easier to install. Line-voltage models are available for permanent hardwired installs — call to confirm."},{"q":"Will these survive a Canadian winter?","a":"Yes — these fixtures are IP65-rated with cold-rated LEDs and drivers, tested well below typical Ontario winter temperatures."}]'::jsonb, '/images/products/brand-votatec-transformer-for-landscape-lighting-8211-88w.webp');
