insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-cct-038-power-selectable-linear-strip-fixture-sensor-8211-90', 'VOTATEC-038POWERSELECTABLELINEARSTRIPFIX', 'CCT & Power Selectable Linear Strip Fixture Sensor 90W-8ft', 'residential-lighting', 'led-strip-light', 0, null, false, '8ft linkable LED strip with motion sensor, 50W to 90W selectable, 130Lm/W, 5-CCT (3500K to 5700K), AC120-347V, IP20. Warehouse and shop. Get a quote.', '8ft linkable LED strip with motion sensor, 50W to 90W selectable, 130Lm/W, 5-CCT (3500K to 5700K), AC120-347V, IP20. Warehouse and shop. Get a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'CCT & Power Selectable Linear Stri…', 'Buy the CCT & Power Selectable Linear Strip Fixture Sensor 90W-8ft wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The CCT & Power Selectable Linear Strip Fixture Sensor 90W-8ft is a professional-grade LED strip light system for coves, toe-kicks, shelving and accent runs. Genuine manufacturer product on a flexible tape that cuts to length and sticks in place, with aluminum channel options for a finished architectural look. As a lighting distributor in Mississauga, GSW stocks tape, drivers and channels together so your whole run comes from one supplier.', '[{"q":"12V or 24V — which should I use?","a":"We recommend 24V for runs longer than about 5 metres to avoid voltage drop and dimming at the far end. Both are in stock; tell us the run length and we will size the driver."},{"q":"Is the strip dimmable?","a":"Yes, with a compatible dimmable driver. We can supply the matching driver and dimmer so the whole circuit dims smoothly from one switch."}]'::jsonb, '/images/products/brand-votatec-cct-038-power-selectable-linear-strip-fix