insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-transformer-for-landscape-lighting-8211-120w', 'VOTATEC-FORLANDSCAPELIGHTING8211120W', 'Transformer for Landscape Lighting 120W', 'residential-lighting', 'led-outdoor-garden-light', 0, null, false, 'Landscape lighting transformer, 120W, 120V to 12VAC, 10A, photocell + timer (1-9hr), weatherproof on/off. Low-voltage outdoor lighting. Get a quote.', 'Landscape lighting transformer, 120W, 120V to 12VAC, 10A, photocell + timer (1-9hr), weatherproof on/off. Low-voltage outdoor lighting. Get a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Transformer for Landscape Lighting…', 'Buy the Transformer for Landscape Lighting 120W wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Transformer for Landscape Lighting 120W is a weather-rated LED garden light built to make Ontario landscapes look their best year-round. Genuine manufacturer product in a durable housing that shrugs off rain, snow and hose spray. Landscape contractors and DIY homeowners alike buy garden lighting from GSW’s Mississauga store for the combination of wholesale pricing and in-stock depth.', '[{"q":"Low voltage or line voltage?","a":"Most landscape fixtures run on 12V AC/DC from a transformer, which is safer to bury and easier to install. Line-voltage models are available for permanent hardwired installs — call to confirm."},{"q":"Will these survive a Canadian winter?","a":"Yes — these fixtures are IP65-rated with cold-rated LEDs and drivers, tested well below typical Ontario winter temperatures."}]'::jsonb, '/images/products/brand-votatec-transformer-for-landscape-lighting-8211-120w.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-8-slim-round-panel-led-5way-cct-adjustable-8211-ac120-347v', 'VOTATEC-SLIMROUNDPANELLED5WAYCCTADJUSTAB', '8 Slim Round Panel LED 5Way CCT Adjustable AC120-347V', 'residential-lighting', 'led-gimbals', 0, null, false, '8" slim LED panel, 18W, 1700Lm, 5-CCT (2700K to 5000K), AC120-347V, 0-10V dimming, Energy Star, ETL. Office and retail retrofit. Request a quote.', '8" slim LED panel, 18W, 1700Lm, 5-CCT (2700K to 5000K), AC120-347V, 0-10V dimming, Energy Star, ETL. Office and retail retrofit. Request a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '8 Slim Round Panel LED 5Way CCT Ad…', 'Buy the 8 Slim Round Panel LED 5Way CCT Adjustable AC120-347V wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The 8 Slim Round Panel LED 5Way CCT Adjustable AC120-347V is an adjustable LED gimbal downlight that lets you aim light exactly where the design calls for it — artwork, feature walls, kitchen islands and sloped ceilings. Genuine manufacturer product in a compact trim that disappears into the ceiling. GSW stocks 3-inch and 4-inch gimbals at our Mississauga electrical supply store for same-day contractor pickup, with flat $30 shipping across Canada.', '[{"q":"How much can a gimbal tilt?","a":"Most of our gimbals tilt 30–35 degrees and swivel a full 360 degrees, so one fixture position can serve multiple aiming points without moving the ceiling box."},{"q":"Can I use gimbals in an insulated ceiling?","a":"Yes. These fixtures are IC-rated for direct contact with insulation, provided the fixture is installed according to the listing."}]'::jsonb, '/images/products/brand-votatec-8-slim-round-panel-led-5way-cct-adjustable-8211-ac120-347v.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-4ft-linear-high-bay-8211-cct-038-power-adjustable', 'VOTATEC-LINEARHIGHBAY8211CCT038POWERADJU', '4ft Linear High Bay CCT & Power Adjustable', 'industrial-lighting', 'led-ufo-high-bay', 0, null, false, '4ft linear LED high bay, 160W/220W/300W selectable, 150Lm/W, 3500K/4000K/5000K, AC120-347V. Remote and sensor ready. Industrial use. Get a quote.', '4ft linear LED high bay, 160W/220W/300W selectable, 150Lm/W, 3500K/4000K/5000K, AC120-347V. Remote and sensor ready. Industrial use. Get a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '4ft Linear High Bay CCT & Power Ad…', 'Buy the 4ft Linear High Bay CCT & Power Adjustable wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The 4ft Linear High Bay CCT & Power Adjustable is an industrial LED UFO high bay for warehouses, gymnasiums and manufacturing floors. Genuine manufacturer product with high-efficiency optics that put light on the floor, not the walls. GSW is a Canadian wholesale supplier of LED high bay lights, stocking 100W–240W UFOs with DLC Premium listings, hook mounts included, and flat $30 shipping to any industrial job site.', '[{"q":"How many high bays do I need for my warehouse?","a":"It depends on mounting height, racking layout and required foot-candles. As a guide, 150W UFOs on 4–5 metre centres serve most 6–8 metre warehouses well. Send us the floor plan and we will estimate quantities and spacing for free."},{"q":"UFO or linear high bay — which is better?","a":"UFOs are compact, quick to hang and ideal for open areas and lower ceilings. Linear high bays with aisle optics win in racked warehouses where light must travel down narrow aisles. Call us with the layout and we will recommend the right optic."}]'::jsonb, '/images/products/brand-votatec-4ft-linear-high-bay-8211-cct-038-power-adjustable.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-led-corn-light-8211-18w-clw07e', 'VOTATEC-CORNLIGHT821118WCLW07E', 'LED Corn Light 18W-CLW07E', 'commercial-lighting', 'led-retrofit-corn-light', 0, null, false, '18W LED corn bulb replaces metal halide and HPS lamps in post tops, high bays, and wall packs. E26/E27 base. Bulk wholesale orders welcome.', '18W LED corn bulb replaces metal halide and HPS lamps in post tops, high bays, and wall packs. E26/E27 base. Bulk wholesale orders welcome.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'LED Corn Light 18W-CLW07E Canada', 'Buy the LED Corn Light 18W-CLW07E wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The LED Corn Light 18W-CLW07E is an LED corn light that retrofits HID lamps — metal halide and high-pressure sodium — without replacing the fixture. Genuine manufacturer product on a mogul base that screws straight into the existing socket after a ballast bypass. Contractors retrofitting post tops, wall packs and high bays buy corn lights from GSW at wholesale pricing with same-day GTA pickup.', '[{"q":"Do I remove the ballast?","a":"Yes — corn lamps operate on line voltage and require a ballast bypass (direct wire). It is a straightforward change our customers do every day; if you are unsure, any licensed electrician can handle it quickly."},{"q":"What HID wattage does this replace?","a":"Genuine manufacturer product typically replaces a 400W HID lamp at roughly half the energy draw and many times the rated life."}]'::jsonb, '/images/products/brand-votatec-led-corn-light-8211-18w-clw07e.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-2-8243-round-baffle-downlight-5way-cct', 'VOTATEC-8243ROUNDBAFFLEDOWNLIGHT5WAYCCT', '2 Round Baffle Downlight 5Way CCT', 'residential-lighting', 'led-recessed-down-light', 0, null, false, '2" round baffle LED downlight, 8W, 650Lm, 5-CCT (2700K to 5000K), 40 beam, 120V, CRI >90. Integral driver in junction box. Request a quote.', '2" round baffle LED downlight, 8W, 650Lm, 5-CCT (2700K to 5000K), 40 beam, 120V, CRI >90. Integral driver in junction box. Request a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '2 Round Baffle Downlight 5Way CCT', 'Buy the 2 Round Baffle Downlight 5Way CCT wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The 2 Round Baffle Downlight 5Way CCT is a commercial-grade recessed LED downlight with the colour quality and glare control specifiers ask for. Genuine manufacturer product, with high CRI that makes finishes and merchandise look right. Toronto-area electrical contractors source commercial downlights from GSW because we stock project quantities and match spec sheets item for item.', '[{"q":"What does 90+ CRI mean for my project?","a":"CRI measures colour accuracy. A 90+ CRI downlight renders materials and skin tones faithfully — the standard for retail, galleries and healthcare, and a noticeable upgrade over 80 CRI economy fixtures."},{"q":"Can these dim on my existing controls?","a":"We stock versions dimmable by TRIAC, ELV and 0-10V. Send us the switch or control schedule and we will match the exact driver variant."}]'::jsonb, '/images/products/brand-votatec-2-8243-round-baffle-downlight-5way-cct.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-motion-sensor-switch', 'VOTATEC-SENSORSWITCH', 'Motion Sensor Switch', 'residential-lighting', 'led-motion-sensor-light', 0, null, false, 'Motion sensor wall switch, 120V/60Hz, 1000W tungsten rating, single-pole, indoor, UL773A listed. 3-mode sensing, neutral wire required. Get a quote.', 'Motion sensor wall switch, 120V/60Hz, 1000W tungsten rating, single-pole, indoor, UL773A listed. 3-mode sensing, neutral wire required. Get a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Motion Sensor Switch Canada', 'Buy the Motion Sensor Switch wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Motion Sensor Switch is a motion-activated LED security light that switches on when it matters and stays off when it does not. Genuine manufacturer product with adjustable sensing so you cover the entry, driveway or yard without nuisance trips. GSW is an electrical wholesaler supplying motion sensor lighting across the GTA with contractor pricing and counter pickup in Mississauga.', '[{"q":"Can I adjust the sensitivity and timer?","a":"Yes — the PIR range, dwell time and lux threshold are all field-adjustable, so the light only triggers at night and only when you want it to."},{"q":"Is hardwiring required?","a":"These are hardwired 120V fixtures. For areas without a nearby box, ask us about solar or plug-in alternatives when you call."}]'::jsonb, '/images/products/brand-votatec-motion-sensor-switch.webp');
