insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-cage-vapor-proof-fixture-8211-wall-mount', 'VOTATEC-VAPORPROOFFIXTURE8211WALLMOUNT', 'Cage Vapor-Proof Fixture Wall Mount', 'industrial-lighting', 'led-vapor-tight-fixture', 0, null, false, 'Cage vapor-proof fixture, wall mount, 100W max, E26 A19 socket, die-cast aluminum guard, frosted glass lens, wet-location UL certified. Get a quote.', 'Cage vapor-proof fixture, wall mount, 100W max, E26 A19 socket, die-cast aluminum guard, frosted glass lens, wet-location UL certified. Get a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Cage Vapor-Proof Fixture Wall Mount', 'Buy the Cage Vapor-Proof Fixture Wall Mount wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Cage Vapor-Proof Fixture Wall Mount is a sealed, gasketed LED vapor tight fixture for parking garages, car washes, tunnels and cold storage. Genuine manufacturer product behind an impact-resistant lens that keeps out moisture, dust and corrosion. Contractors building parkades and wash bays across Canada buy vapor tight lighting from GSW for the IP65/IP66 rating depth and fast flat-rate shipping.', '[{"q":"IP65 vs IP66 — what is the difference?","a":"Both are dust-tight and hose-proof; IP66 adds protection against powerful jets, which matters in wash-down and pressure-wash environments. We stock both — tell us the cleaning regime and we will spec it."},{"q":"Does it handle cold temperatures?","a":"Yes — LED vapor tights with quality drivers start reliably well below freezing, making them the standard for unheated parkades and cold storage across Canada."}]'::jsonb, '/images/products/brand-votatec-cage-vapor-proof-fixture-8211-wall-mount.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-indoor-track-light-8211-cct-adjustable', 'VOTATEC-TRACKLIGHT8211CCTADJUSTABLE', 'Indoor Track Light CCT Adjustable', 'residential-lighting', 'led-gimbals', 0, null, false, 'Indoor LED track light, 10W, 900Lm, 5-CCT (2700K to 5000K), 36 beam, 120V, Halo base, CRI >90. Retail and gallery accent. Request a quote.', 'Indoor LED track light, 10W, 900Lm, 5-CCT (2700K to 5000K), 36 beam, 120V, Halo base, CRI >90. Retail and gallery accent. Request a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Indoor Track Light CCT Adjustable', 'Buy the Indoor Track Light CCT Adjustable wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Indoor Track Light CCT Adjustable is an adjustable LED gimbal downlight that lets you aim light exactly where the design calls for it — artwork, feature walls, kitchen islands and sloped ceilings. Genuine manufacturer product in a compact trim that disappears into the ceiling. GSW stocks 3-inch and 4-inch gimbals at our Mississauga electrical supply store for same-day contractor pickup, with flat $30 shipping across Canada.', '[{"q":"How much can a gimbal tilt?","a":"Most of our gimbals tilt 30–35 degrees and swivel a full 360 degrees, so one fixture position can serve multiple aiming points without moving the ceiling box."},{"q":"Can I use gimbals in an insulated ceiling?","a":"Yes. These fixtures are IC-rated for direct contact with insulation, provided the fixture is installed according to the listing."}]'::jsonb, '/images/products/brand-votatec-indoor-track-light-8211-cct-adjustable.webp');
