insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-6-8243-slim-panel-fire-rated-8211-5-way-cct', 'VOTATEC-8243SLIMPANELFIRERATED82115WAYCC', '6 Slim Panel Fire Rated 5 Way CCT', 'residential-lighting', 'led-slim-panel', 0, null, false, '6" slim LED panel, 2-hour fire rated (UL 263 / ASTM E 119), 13W, 1100Lm, 5-CCT (2700K to 5000K), 120V, damp-rated, dimmable. Request a quote.', '6" slim LED panel, 2-hour fire rated (UL 263 / ASTM E 119), 13W, 1100Lm, 5-CCT (2700K to 5000K), 120V, damp-rated, dimmable. Request a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '6 Slim Panel Fire Rated 5 Way CCT', 'Buy the 6 Slim Panel Fire Rated 5 Way CCT wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The 6 Slim Panel Fire Rated 5 Way CCT is an ultra-thin LED panel light designed for fast residential installs where a traditional pot light housing will not fit. Genuine manufacturer product, with selectable colour temperature so the whole home matches from room to room. Because GSW is a lighting distributor serving Mississauga, Toronto and the wider GTA, contractors can pick these panels up at the counter or have them shipped flat-rate anywhere in Canada — at true wholesale pricing.', '[{"q":"Do these slim panels need a housing?","a":"No — the driver and junction box are built into the panel, so it mounts directly to drywall with spring clips. They are IC-rated and wet-location approved, which also makes them suitable for showers and soffits."},{"q":"Are the slim panels dimmable?","a":"Yes, most models dim smoothly to 10% with standard TRIAC wall dimmers. If your project uses 0-10V dimming, call the counter and we will match the right driver."}]'::jsonb, '/images/products/brand-votatec-6-8243-slim-panel-fire-rated-8211-5-way-cct.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-regular-wall-pack-cct-038-power-adjustable-8211-120w', 'VOTATEC-WALLPACKCCT038POWERADJUSTABLE821', 'Regular Wall Pack- CCT &Power Adjustable 120W', 'commercial-lighting', 'led-wall-pack', 0, null, false, 'LED wall pack, 60W/80W/100W/120W selectable, 150Lm/W, Type IV distribution, CCT switchable, AC120-347V, IP65, photocell. Get a quote.', 'LED wall pack, 60W/80W/100W/120W selectable, 150Lm/W, Type IV distribution, CCT switchable, AC120-347V, IP65, photocell. Get a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Regular Wall Pack- CCT &Power Adju…', 'Buy the Regular Wall Pack- CCT &Power Adjustable 120W wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Regular Wall Pack- CCT &Power Adjustable 120W is a full-cutoff LED wall pack for building perimeters, loading docks and egress routes. Genuine manufacturer product with a photocell option so the light manages itself from dusk to dawn. Commercial contractors across Toronto and the GTA buy LED wall packs wholesale from GSW for the mix of DLC-listed product, real stock and counter pickup in Mississauga.', '[{"q":"Does the wall pack include a photocell?","a":"Most of our wall packs accept a twist-lock photocell and several ship with one included — check the spec table on this model. We always confirm the configuration when you order by phone."},{"q":"Full cutoff — what does that mean?","a":"A full-cutoff optic directs all light downward, eliminating uplight and meeting dark-sky and light-trespass requirements common in GTA municipalities."}]'::jsonb, '/images/products/brand-votatec-regular-wall-pack-cct-038-power-adjustable-8211-120w.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-transformer-for-landscape-lighting-8211-300w-8211-dimension-', 'VOTATEC-FORLANDSCAPELIGHTING8211300W8211', 'Transformer for Landscape Lighting 300W Dimension 5.5 x3.77 x8.15', 'residential-lighting', 'led-outdoor-garden-light', 0, null, false, 'Landscape lighting transformer, 300W, 120V to 12VAC, 25A, slim 5.5"x3.77"x8.15", photocell + 2/4/6/8hr timer, IP44, ETL. Request a quote.', 'Landscape lighting transformer, 300W, 120V to 12VAC, 25A, slim 5.5"x3.77"x8.15", photocell + 2/4/6/8hr timer, IP44, ETL. Request a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Transformer for Landscape Lighting…', 'Buy the Transformer for Landscape Lighting 300W Dimension 5.5 x3.77 x8.15 wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 s…', 'The Transformer for Landscape Lighting 300W Dimension 5.5 x3.77 x8.15 is a weather-rated LED garden light built to make Ontario landscapes look their best year-round. Genuine manufacturer product in a durable housing that shrugs off rain, snow and hose spray. Landscape contractors and DIY homeowners alike buy garden lighting from GSW’s Mississauga store for the combination of wholesale pricing and in-stock depth.', '[{"q":"Low voltage or line voltage?","a":"Most landscape fixtures run on 12V AC/DC from a transformer, which is safer to bury and easier to install. Line-voltage models are available for permanent hardwired installs — call to confirm."},{"q":"Will these survive a Canadian winter?","a":"Yes — these fixtures are IP65-rated with cold-rated LEDs and drivers, tested well below typical Ontario winter temperatures."}]'::jsonb, '/images/products/brand-votatec-transformer-for-landscape-lighting-8211-300w-8211-dimension-.webp');
