insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-full-cut-off-wall-pack-cct-038-power-adjustable', 'VOTATEC-CUTOFFWALLPACKCCT038POWERADJUSTA', 'Full Cut-off Wall Pack- CCT &Power Adjustable', 'commercial-lighting', 'led-wall-pack', 0, null, false, 'Full cut-off LED wall pack, 60W/80W/100W/120W selectable, 130Lm/W, Type III, CCT switchable, AC120-347V, IP65, photocell. Get a quote.', 'Full cut-off LED wall pack, 60W/80W/100W/120W selectable, 130Lm/W, Type III, CCT switchable, AC120-347V, IP65, photocell. Get a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Full Cut-off Wall Pack- CCT &Power…', 'Buy the Full Cut-off Wall Pack- CCT &Power Adjustable wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Full Cut-off Wall Pack- CCT &Power Adjustable is a full-cutoff LED wall pack for building perimeters, loading docks and egress routes. Genuine manufacturer product with a photocell option so the light manages itself from dusk to dawn. Commercial contractors across Toronto and the GTA buy LED wall packs wholesale from GSW for the mix of DLC-listed product, real stock and counter pickup in Mississauga.', '[{"q":"Does the wall pack include a photocell?","a":"Most of our wall packs accept a twist-lock photocell and several ship with one included — check the spec table on this model. We always confirm the configuration when you order by phone."},{"q":"Full cutoff — what does that mean?","a":"A full-cutoff optic directs all light downward, eliminating uplight and meeting dark-sky and light-trespass requirements common in GTA municipalities."}]'::jsonb, '/images/products/brand-votatec-full-cut-off-wall-pack-cct-038-power-adjustable.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-9-8243-pir-sensor-slim-flush-mount-led-3way-cct', 'VOTATEC-8243PIRSENSORSLIMFLUSHMOUNTLED3W', '9 PIR Sensor Slim Flush Mount LED- 3Way CCT', 'residential-lighting', 'led-motion-sensor-light', 0, null, false, '9" PIR motion-sensor LED flush mount, 18W, 1440Lm, 3-CCT (3000K/4000K/5000K), 120V, 120 beam, dimmable. Closet, pantry, hallway. Get a quote.', '9" PIR motion-sensor LED flush mount, 18W, 1440Lm, 3-CCT (3000K/4000K/5000K), 120V, 120 beam, dimmable. Closet, pantry, hallway. Get a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '9 PIR Sensor Slim Flush Mount LED-…', 'Buy the 9 PIR Sensor Slim Flush Mount LED- 3Way CCT wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The 9 PIR Sensor Slim Flush Mount LED- 3Way CCT is a motion-activated LED security light that switches on when it matters and stays off when it does not. Genuine manufacturer product with adjustable sensing so you cover the entry, driveway or yard without nuisance trips. GSW is an electrical wholesaler supplying motion sensor lighting across the GTA with contractor pricing and counter pickup in Mississauga.', '[{"q":"Can I adjust the sensitivity and timer?","a":"Yes — the PIR range, dwell time and lux threshold are all field-adjustable, so the light only triggers at night and only when you want it to."},{"q":"Is hardwiring required?","a":"These are hardwired 120V fixtures. For areas without a nearby box, ask us about solar or plug-in alternatives when you call."}]'::jsonb, '/images/products/brand-votatec-9-8243-pir-sensor-slim-flush-mount-led-3way-cct.webp');
