insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-t50-filament-led', 'VOTATEC-FILAMENTLED-13', 'T50 Filament LED', 'commercial-lighting', 'led-retrofit-corn-light', 0, null, false, 'T50 LED filament bulb, 9W, 1000Lm, 3000K/4000K, E26 base, 360 beam, 120V, dimmable, CRI >80, 50,000-hour life. Long tubular vintage. Get a quote.', 'T50 LED filament bulb, 9W, 1000Lm, 3000K/4000K, E26 base, 360 beam, 120V, dimmable, CRI >80, 50,000-hour life. Long tubular vintage. Get a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'T50 Filament LED Canada', 'Buy the T50 Filament LED wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The T50 Filament LED is an LED corn light that retrofits HID lamps — metal halide and high-pressure sodium — without replacing the fixture. Genuine manufacturer product on a mogul base that screws straight into the existing socket after a ballast bypass. Contractors retrofitting post tops, wall packs and high bays buy corn lights from GSW at wholesale pricing with same-day GTA pickup.', '[{"q":"Do I remove the ballast?","a":"Yes — corn lamps operate on line voltage and require a ballast bypass (direct wire). It is a straightforward change our customers do every day; if you are unsure, any licensed electrician can handle it quickly."},{"q":"What HID wattage does this replace?","a":"Genuine manufacturer product typically replaces a 400W HID lamp at roughly half the energy draw and many times the rated life."}]'::jsonb, '/images/products/brand-votatec-t50-filament-led.webp');
