insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-mini-step-led-light-8211-square', 'VOTATEC-STEPLEDLIGHT8211SQUARE', 'Mini Step LED Light Square', 'residential-lighting', 'led-outdoor-garden-light', 0, null, false, 'Mini square step LED, 1W, 18Lm, 3000K, 2" face, 12V input, die-cast aluminum, damp-location rated, ETL. Stair and pathway accent. Request a quote.', 'Mini square step LED, 1W, 18Lm, 3000K, 2" face, 12V input, die-cast aluminum, damp-location rated, ETL. Stair and pathway accent. Request a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Mini Step LED Light Square Canada', 'Buy the Mini Step LED Light Square wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Mini Step LED Light Square is a weather-rated LED garden light built to make Ontario landscapes look their best year-round. Genuine manufacturer product in a durable housing that shrugs off rain, snow and hose spray. Landscape contractors and DIY homeowners alike buy garden lighting from GSW’s Mississauga store for the combination of wholesale pricing and in-stock depth.', '[{"q":"Low voltage or line voltage?","a":"Most landscape fixtures run on 12V AC/DC from a transformer, which is safer to bury and easier to install. Line-voltage models are available for permanent hardwired installs — call to confirm."},{"q":"Will these survive a Canadian winter?","a":"Yes — these fixtures are IP65-rated with cold-rated LEDs and drivers, tested well below typical Ontario winter temperatures."}]'::jsonb, '/images/products/brand-votatec-mini-step-led-light-8211-square.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-plate-for-3-5-8243-led-combo-downlight', 'VOTATEC-FOR358243LEDCOMBODOWNLIGHT', 'Plate For 3.5 Led Combo Downlight', 'residential-lighting', 'led-recessed-down-light', 0, null, false, 'Mounting plate for 3.5" LED combo downlight, no-lip, 13-3/16" x 3-11/16", fits new-construction housings. Quick install. Request a quote.', 'Mounting plate for 3.5" LED combo downlight, no-lip, 13-3/16" x 3-11/16", fits new-construction housings. Quick install. Request a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Plate For 3.5 Led Combo Downlight', 'Buy the Plate For 3.5 Led Combo Downlight wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Plate For 3.5 Led Combo Downlight is a commercial-grade recessed LED downlight with the colour quality and glare control specifiers ask for. Genuine manufacturer product, with high CRI that makes finishes and merchandise look right. Toronto-area electrical contractors source commercial downlights from GSW because we stock project quantities and match spec sheets item for item.', '[{"q":"What does 90+ CRI mean for my project?","a":"CRI measures colour accuracy. A 90+ CRI downlight renders materials and skin tones faithfully — the standard for retail, galleries and healthcare, and a noticeable upgrade over 80 CRI economy fixtures."},{"q":"Can these dim on my existing controls?","a":"We stock versions dimmable by TRIAC, ELV and 0-10V. Send us the switch or control schedule and we will match the exact driver variant."}]'::jsonb, '/images/products/brand-votatec-plate-for-3-5-8243-led-combo-downlight.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-2ft-linear-high-bay-8211-cct-038-power-adjustable', 'VOTATEC-LINEARHIGHBAY8211CCT038POWERADJU-2', '2ft Linear High Bay CCT & Power Adjustable', 'industrial-lighting', 'led-ufo-high-bay', 0, null, false, '2ft linear LED high bay, 110W/165W/220W selectable, 150Lm/W, 3-CCT (3500K/4000K/5000K), AC120-347V, 90 beam, sensor + remote. Get a quote.', '2ft linear LED high bay, 110W/165W/220W selectable, 150Lm/W, 3-CCT (3500K/4000K/5000K), AC120-347V, 90 beam, sensor + remote. Get a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '2ft Linear High Bay CCT & Power Ad…', 'Buy the 2ft Linear High Bay CCT & Power Adjustable wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The 2ft Linear High Bay CCT & Power Adjustable is an industrial LED UFO high bay for warehouses, gymnasiums and manufacturing floors. Genuine manufacturer product with high-efficiency optics that put light on the floor, not the walls. GSW is a Canadian wholesale supplier of LED high bay lights, stocking 100W–240W UFOs with DLC Premium listings, hook mounts included, and flat $30 shipping to any industrial job site.', '[{"q":"How many high bays do I need for my warehouse?","a":"It depends on mounting height, racking layout and required foot-candles. As a guide, 150W UFOs on 4–5 metre centres serve most 6–8 metre warehouses well. Send us the floor plan and we will estimate quantities and spacing for free."},{"q":"UFO or linear high bay — which is better?","a":"UFOs are compact, quick to hang and ideal for open areas and lower ceilings. Linear high bays with aisle optics win in racked warehouses where light must travel down narrow aisles. Call us with the layout and we will recommend the right optic."}]'::jsonb, '/images/products/brand-votatec-2ft-linear-high-bay-8211-cct-038-power-adjustable.webp');
