insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-bathroom-fan-led-panel', 'VOTATEC-FANLEDPANEL', 'Bathroom Fan LED Panel', 'residential-lighting', 'bathroom-exhaust-fan', 0, null, false, 'Add-on LED panel for bathroom fans, 16W, 1000Lm, 5-CCT (2700K to 5000K), 11.43" diameter, with connector wire. Easy retrofit upgrade. Get a quote.', 'Add-on LED panel for bathroom fans, 16W, 1000Lm, 5-CCT (2700K to 5000K), 11.43" diameter, with connector wire. Easy retrofit upgrade. Get a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Bathroom Fan LED Panel Canada', 'Buy the Bathroom Fan LED Panel wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Bathroom Fan LED Panel is an ENERGY STAR-rated bathroom exhaust fan that clears moisture quietly and reliably. Genuine manufacturer product — sized for real bathrooms with the duct connections and grilles contractors prefer. Builders and renovators across Mississauga and Toronto buy exhaust fans from GSW at wholesale pricing with volume stock for multi-bathroom jobs.', '[{"q":"What CFM do I need for my bathroom?","a":"Rule of thumb: 1 CFM per square foot of bathroom, minimum 50 CFM, and add capacity for high ceilings or jetted tubs. An 80 CFM fan covers most standard bathrooms; large ensuites may want 110 CFM."},{"q":"What does \"sones\" mean?","a":"Sones measure perceived loudness — lower is quieter. Under 1.0 sone is nearly inaudible; 3+ sones is clearly noticeable. We stock quiet models because homeowners complain about noise more than any other fan spec."}]'::jsonb, '/images/products/brand-votatec-bathroom-fan-led-panel.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-led-hardscape-light-8211-4-5w', 'VOTATEC-HARDSCAPELIGHT821145W', 'LED Hardscape Light 4.5W', 'residential-lighting', 'led-ceiling-fixture', 0, null, false, 'LED hardscape light, 4.5W, 310Lm, 5-CCT (2700K to 5000K), AC/DC 12-24V, 7" length, cast aluminum, IP65. Deck, wall, garden accent. Get a quote.', 'LED hardscape light, 4.5W, 310Lm, 5-CCT (2700K to 5000K), AC/DC 12-24V, 7" length, cast aluminum, IP65. Deck, wall, garden accent. Get a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'LED Hardscape Light 4.5W Canada', 'Buy the LED Hardscape Light 4.5W wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The LED Hardscape Light 4.5W is a surface-mount LED ceiling fixture built for dependable, maintenance-free residential light. Genuine manufacturer product, with a diffuser that spreads light evenly and hides hotspots. Contractors across Mississauga, Brampton and Toronto choose GSW for ceiling fixtures because we keep depth of stock, quote real wholesale pricing, and can stage full floor packages for multi-unit jobs.', '[{"q":"Are these fixtures dimmable?","a":"Many models are dimmable to 10–20% with standard wall dimmers — check the spec row for \"dimmable\" on this model, or call us and we will confirm compatibility before you buy."},{"q":"Do you sell matching fixtures for a whole building?","a":"Yes. We regularly stage identical fixture packages for multi-unit residential jobs. Call +1 416-951-2650 with your counts and we will hold stock under one SKU."}]'::jsonb, '/images/products/brand-votatec-led-hardscape-light-8211-4-5w.webp');
