insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-lvl-8211-landscape-cable', 'VOTATEC-8211LANDSCAPECABLE', 'LVL Landscape Cable', 'residential-lighting', 'led-outdoor-garden-light', 0, null, false, 'LVL landscape lighting cable, 150V, stranded bare copper conductors, PVC jacket resistant to water and abrasion. UL/cUL/CSA listed. Sizes #12 to #16. Get a quot', 'LVL landscape lighting cable, 150V, stranded bare copper conductors, PVC jacket resistant to water and abrasion. UL/cUL/CSA listed. Sizes #12 to #16. Get a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'LVL Landscape Cable Canada', 'Buy the LVL Landscape Cable wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The LVL Landscape Cable is a weather-rated LED garden light built to make Ontario landscapes look their best year-round. Genuine manufacturer product in a durable housing that shrugs off rain, snow and hose spray. Landscape contractors and DIY homeowners alike buy garden lighting from GSW’s Mississauga store for the combination of wholesale pricing and in-stock depth.', '[{"q":"Low voltage or line voltage?","a":"Most landscape fixtures run on 12V AC/DC from a transformer, which is safer to bury and easier to install. Line-voltage models are available for permanent hardwired installs — call to confirm."},{"q":"Will these survive a Canadian winter?","a":"Yes — these fixtures are IP65-rated with cold-rated LEDs and drivers, tested well below typical Ontario winter temperatures."}]'::jsonb, '/images/products/brand-votatec-lvl-8211-landscape-cable.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-led-area-light-8211-cct-038-power-038-beam-angle-switch-adju', 'VOTATEC-AREALIGHT8211CCT038POWER038BEAMA', 'LED Area Light CCT & Power & Beam Angle Switch Adjustable', 'commercial-lighting', 'led-outdoor-shoebox-light', 0, null, false, 'ED area light with T3/T4/T5 beam switch, 200W/240W/300W selectable, 30000-45000Lm, CCT switchable, IP66, AC120-347V. Tunable distribution. Get a quote', 'ED area light with T3/T4/T5 beam switch, 200W/240W/300W selectable, 30000-45000Lm, CCT switchable, IP66, AC120-347V. Tunable distribution. Get a quote', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'LED Area Light CCT & Power & Beam…', 'Buy the LED Area Light CCT & Power & Beam Angle Switch Adjustable wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The LED Area Light CCT & Power & Beam Angle Switch Adjustable is an LED shoebox area light for parking lots, roadways and big-box retail sites. Genuine manufacturer product with field-selectable optics and an included photocell for dusk-to-dawn operation. Canadian contractors buy shoebox lighting wholesale from GSW — DLC-listed product, 10kV surge protection options, and flat-rate shipping to any job site in the country.', '[{"q":"Pole mount or wall mount?","a":"Shoeboxes typically mount on poles with a slip-fitter (2-3/8 inch tenon) — we stock adapters for wall and trunnion mounting too. Tell us the pole schedule and we will configure the order."},{"q":"What optic do I need?","a":"Type III throws light forward along roadways and aisles; Type IV is symmetrical for open lots; Type V is a broad square for centred poles. We can help choose from the site plan or photometric."}]'::jsonb, '/images/products/brand-votatec-led-area-light-8211-cct-038-power-038-beam-angle-switch-adju.webp');
