insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-led-flood-light-8211-cct-038-power-adjustable-8211-500w', 'VOTATEC-FLOODLIGHT8211CCT038POWERADJUSTA-2', 'LED Flood Light CCT & Power Adjustable 500W', 'commercial-lighting', 'led-flood-light', 0, null, false, 'High-output LED flood light, 300W/400W/500W selectable, 45000-75000Lm, CCT switchable, IP66 IK08, AC120-347V. Stadium and yard rated. Get a quote.', 'High-output LED flood light, 300W/400W/500W selectable, 45000-75000Lm, CCT switchable, IP66 IK08, AC120-347V. Stadium and yard rated. Get a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'LED Flood Light CCT & Power Adjust…', 'Buy the LED Flood Light CCT & Power Adjustable 500W wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The LED Flood Light CCT & Power Adjustable 500W is a high-output LED flood light engineered for large areas — parking lots, yards, facades and sports surfaces. Genuine manufacturer product with precision optics that put light on the target, not the neighbours. GSW is a Canadian wholesale LED lighting supplier, so flood lights ship flat-rate across the country and are always available for pickup at our Mississauga counter.', '[{"q":"How do I choose wattage for a parking lot?","a":"As a rule of thumb, 100W–150W LED replaces a 400W metal halide shoebox or flood. Tell us the pole height and spacing and we will run a quick layout to confirm foot-candles before you commit."},{"q":"Are these lights dimmable or motion-controllable?","a":"Most models accept 0-10V dimming and pair with motion sensors or photocells for after-hours energy savings. We stock compatible controls."}]'::jsonb, '/images/products/brand-votatec-led-flood-light-8211-cct-038-power-adjustable-8211-500w.webp');
