insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-led-corn-light-8211-multi-voltage-8211-80w-clw07c', 'VOTATEC-CORNLIGHT8211MULTIVOLTAGE821180W', 'LED Corn Light Multi Voltage 80W-CLW07C', 'commercial-lighting', 'led-retrofit-corn-light', 0, null, false, 'ED corn light, 80W, 10800-11600Lm, 4000K/5000K, E39 mogul base, AC120-347V, IP65, dimmable, UL listed. HID replacement. Request a quote.', 'ED corn light, 80W, 10800-11600Lm, 4000K/5000K, E39 mogul base, AC120-347V, IP65, dimmable, UL listed. HID replacement. Request a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'LED Corn Light Multi Voltage 80W-C…', 'Buy the LED Corn Light Multi Voltage 80W-CLW07C wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The LED Corn Light Multi Voltage 80W-CLW07C is an LED corn light that retrofits HID lamps — metal halide and high-pressure sodium — without replacing the fixture. Genuine manufacturer product on a mogul base that screws straight into the existing socket after a ballast bypass. Contractors retrofitting post tops, wall packs and high bays buy corn lights from GSW at wholesale pricing with same-day GTA pickup.', '[{"q":"Do I remove the ballast?","a":"Yes — corn lamps operate on line voltage and require a ballast bypass (direct wire). It is a straightforward change our customers do every day; if you are unsure, any licensed electrician can handle it quickly."},{"q":"What HID wattage does this replace?","a":"Genuine manufacturer product typically replaces a 400W HID lamp at roughly half the energy draw and many times the rated life."}]'::jsonb, '/images/products/brand-votatec-led-corn-light-8211-multi-voltage-8211-80w-clw07c.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-a19-led-5way-cct-adjustable-8211-pir', 'VOTATEC-LED5WAYCCTADJUSTABLE8211PIR', 'A19 LED 5Way CCT Adjustable PIR', 'residential-lighting', 'led-gimbals', 0, null, false, 'A19 LED bulb with PIR motion sensor, 10W, 800Lm, 5-CCT (2700K to 5000K), E26 base, 120V, dimmable, CRI >80. Auto on-off for hallways. Request a quote.', 'A19 LED bulb with PIR motion sensor, 10W, 800Lm, 5-CCT (2700K to 5000K), E26 base, 120V, dimmable, CRI >80. Auto on-off for hallways. Request a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'A19 LED 5Way CCT Adjustable PIR', 'Buy the A19 LED 5Way CCT Adjustable PIR wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The A19 LED 5Way CCT Adjustable PIR is an adjustable LED gimbal downlight that lets you aim light exactly where the design calls for it — artwork, feature walls, kitchen islands and sloped ceilings. Genuine manufacturer product in a compact trim that disappears into the ceiling. GSW stocks 3-inch and 4-inch gimbals at our Mississauga electrical supply store for same-day contractor pickup, with flat $30 shipping across Canada.', '[{"q":"How much can a gimbal tilt?","a":"Most of our gimbals tilt 30–35 degrees and swivel a full 360 degrees, so one fixture position can serve multiple aiming points without moving the ceiling box."},{"q":"Can I use gimbals in an insulated ceiling?","a":"Yes. These fixtures are IC-rated for direct contact with insulation, provided the fixture is installed according to the listing."}]'::jsonb, '/images/products/brand-votatec-a19-led-5way-cct-adjustable-8211-pir.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-12-8243-pir-sensor-slim-flush-mount-8211-5way-cct', 'VOTATEC-8243PIRSENSORSLIMFLUSHMOUNT82115', '12 PIR Sensor Slim Flush Mount 5Way CCT', 'residential-lighting', 'led-motion-sensor-light', 0, null, false, '12" PIR motion-sensor LED flush mount, 24W, 1920Lm, 5-CCT (2700K to 5000K), 120V, IP44, dimmable. Garage and hallway. Request a quote.', '12" PIR motion-sensor LED flush mount, 24W, 1920Lm, 5-CCT (2700K to 5000K), 120V, IP44, dimmable. Garage and hallway. Request a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '12 PIR Sensor Slim Flush Mount 5Wa…', 'Buy the 12 PIR Sensor Slim Flush Mount 5Way CCT wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The 12 PIR Sensor Slim Flush Mount 5Way CCT is a motion-activated LED security light that switches on when it matters and stays off when it does not. Genuine manufacturer product with adjustable sensing so you cover the entry, driveway or yard without nuisance trips. GSW is an electrical wholesaler supplying motion sensor lighting across the GTA with contractor pricing and counter pickup in Mississauga.', '[{"q":"Can I adjust the sensitivity and timer?","a":"Yes — the PIR range, dwell time and lux threshold are all field-adjustable, so the light only triggers at night and only when you want it to."},{"q":"Is hardwiring required?","a":"These are hardwired 120V fixtures. For areas without a nearby box, ask us about solar or plug-in alternatives when you call."}]'::jsonb, '/images/products/brand-votatec-12-8243-pir-sensor-slim-flush-mount-8211-5way-cct.webp');
