insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-led-corn-light-8211-multi-voltage-8211-45w-clw07c', 'VOTATEC-CORNLIGHT8211MULTIVOLTAGE821145W', 'LED Corn Light Multi Voltage 45W-CLW07C', 'commercial-lighting', 'led-retrofit-corn-light', 0, null, false, 'LED corn light, 45W, 5850-6300Lm, 4000K/5000K, E26/E39 base, AC120-347V, IP65, dimmable, 50,000-hour life. HID retrofit. Request a quote.', 'LED corn light, 45W, 5850-6300Lm, 4000K/5000K, E26/E39 base, AC120-347V, IP65, dimmable, 50,000-hour life. HID retrofit. Request a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'LED Corn Light Multi Voltage 45W-C…', 'Buy the LED Corn Light Multi Voltage 45W-CLW07C wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The LED Corn Light Multi Voltage 45W-CLW07C is an LED corn light that retrofits HID lamps — metal halide and high-pressure sodium — without replacing the fixture. Genuine manufacturer product on a mogul base that screws straight into the existing socket after a ballast bypass. Contractors retrofitting post tops, wall packs and high bays buy corn lights from GSW at wholesale pricing with same-day GTA pickup.', '[{"q":"Do I remove the ballast?","a":"Yes — corn lamps operate on line voltage and require a ballast bypass (direct wire). It is a straightforward change our customers do every day; if you are unsure, any licensed electrician can handle it quickly."},{"q":"What HID wattage does this replace?","a":"Genuine manufacturer product typically replaces a 400W HID lamp at roughly half the energy draw and many times the rated life."}]'::jsonb, '/images/products/brand-votatec-led-corn-light-8211-multi-voltage-8211-45w-clw07c.webp');
