insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-waterproof-dual-head-emergency', 'VOTATEC-DUALHEADEMERGENCY', 'Waterproof Dual Head Emergency', 'commercial-lighting', 'exit-emergency-led-lighting', 0, null, false, 'Waterproof dual head LED emergency light, 2W, 175Lm, 6500K, AC120-347V, IP65 wet-location, 2-hour duration, UL listed. Get a quote.', 'Waterproof dual head LED emergency light, 2W, 175Lm, 6500K, AC120-347V, IP65 wet-location, 2-hour duration, UL listed. Get a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Waterproof Dual Head Emergency', 'Buy the Waterproof Dual Head Emergency wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Waterproof Dual Head Emergency is a cULus-listed exit and emergency lighting unit for code-compliant egress. Genuine manufacturer product with 90-minute battery backup and universal mounting for walls and ceilings. Electrical contractors across Canada buy life-safety lighting from GSW because every unit we ship carries the certifications inspectors look for — and we stock them in depth.', '[{"q":"Does this meet Ontario Fire Code?","a":"Yes — our exit signs and emergency units are cULus listed to CSA 22.2 No. 141 with 90-minute battery backup, meeting Ontario Fire Code and OBC egress requirements. Certificates are available on request."},{"q":"Red or green letters?","a":"Ontario accepts both, but red is the most common choice locally. Most of our units accept either legend — tell us your preference when ordering."}]'::jsonb, '/images/products/brand-votatec-waterproof-dual-head-emergency.webp');
