insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-led-corn-light-8211-multi-voltage-8211-36w-clw07c', 'VOTATEC-CORNLIGHT8211MULTIVOLTAGE821136W', 'LED Corn Light Multi Voltage 36W-CLW07C', 'commercial-lighting', 'led-retrofit-corn-light', 0, null, false, 'LED corn light, 36W, 4680-5050Lm, 4000K/5000K, E26/E39 base, AC120-347V, IP65, dimmable, UL listed. CFL and HID replacement. Get a quote', 'LED corn light, 36W, 4680-5050Lm, 4000K/5000K, E26/E39 base, AC120-347V, IP65, dimmable, UL listed. CFL and HID replacement. Get a quote', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'LED Corn Light Multi Voltage 36W-C…', 'Buy the LED Corn Light Multi Voltage 36W-CLW07C wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The LED Corn Light Multi Voltage 36W-CLW07C is an LED corn light that retrofits HID lamps — metal halide and high-pressure sodium — without replacing the fixture. Genuine manufacturer product on a mogul base that screws straight into the existing socket after a ballast bypass. Contractors retrofitting post tops, wall packs and high bays buy corn lights from GSW at wholesale pricing with same-day GTA pickup.', '[{"q":"Do I remove the ballast?","a":"Yes — corn lamps operate on line voltage and require a ballast bypass (direct wire). It is a straightforward change our customers do every day; if you are unsure, any licensed electrician can handle it quickly."},{"q":"What HID wattage does this replace?","a":"Genuine manufacturer product typically replaces a 400W HID lamp at roughly half the energy draw and many times the rated life."}]'::jsonb, '/images/products/brand-votatec-led-corn-light-8211-multi-voltage-8211-36w-clw07c.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-croc-s-needle-nose-wire-strippers-refurbished', 'RACKATIERS-SNEEDLENOSEWIRESTRIPPERSREFUR', 'Croc''s Needle Nose Wire Strippers - Refurbished', 'residential-lighting', 'led-strip-light', 0, null, false, 'Refurbished Item: Please note these are refurbished models and may show signs of wear or have damaged packaging. They are not eligible for return. Croc s are th', 'Refurbished Item: Please note these are refurbished models and may show signs of wear or have damaged packaging. They are not eligible for return. Croc s are the most versatile and comfortable electrical wire strippers you will ever use. The ergonomic handles are shaped to perfectly fit in your hand while you strip or crimp wire, saving your hands and wrists from soreness. Effortlessly strip stand', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Croc''s Needle Nose Wire Strippers…', 'Buy the Croc''s Needle Nose Wire Strippers - Refurbished wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Croc''s Needle Nose Wire Strippers - Refurbished is a professional-grade LED strip light system for coves, toe-kicks, shelving and accent runs. Genuine manufacturer product on a flexible tape that cuts to length and sticks in place, with aluminum channel options for a finished architectural look. As a lighting distributor in Mississauga, GSW stocks tape, drivers and channels together so your whole run comes from one supplier.', '[{"q":"12V or 24V — which should I use?","a":"We recommend 24V for runs longer than about 5 metres to avoid voltage drop and dimming at the far end. Both are in stock; tell us the run length and we will size the driver."},{"q":"Is the strip dimmable?","a":"Yes, with a compatible dimmable driver. We can supply the matching driver and dimmer so the whole circuit dims smoothly from one switch."}]'::jsonb, '/images/products/brand-rack-a-tiers-croc-s-needle-nose-wire-strippers-refurbished.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-allen-head-7-piece-driver-bit-kit', 'RACKATIERS-HEAD7PIECEDRIVERBITKIT', 'Allen Head 7 Piece Driver Bit Kit', 'commercial-lighting', 'transformer', 0, null, false, 'These high quality hex key Allen bits are 6 long for increased versatility. Also included in the kit is a 3/8 socket adapter. The 1/4 shank', 'These high quality hex key Allen bits are 6 long for increased versatility. Also included in the kit is a 3/8 socket adapter. The 1/4 shank allows you to use any standard drill or quick-change chuck. Rated for use with impact drivers. Kit Includes: 3/16 x 6 Bit 7/32 x 6 Bit 1/4 x 6 Bit 5/16 x 6 Bit 3/8 x 6 B', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Allen Head 7 Piece Driver Bit Kit', 'Buy the Allen Head 7 Piece Driver Bit Kit wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Allen Head 7 Piece Driver Bit Kit is a CSA-certified transformer for stepping service voltages down to usable distribution or control power. Genuine manufacturer product with efficient cores built for continuous duty. Electrical contractors and plant maintenance teams across Canada order transformers from GSW with lead times confirmed up front — made-to-order units are quoted honestly, not optimistically.', '[{"q":"How do I size a transformer?","a":"Sum the connected loads with a diversity factor, check inrush for motor loads, and add 20–25% growth. Send us the load schedule and we will verify the kVA rating and primary/secondary voltages before you order."},{"q":"What is the lead time on made-to-order transformers?","a":"Stock control transformers ship immediately; larger dry-type units typically run 2–4 weeks. We confirm the exact lead time on your quote so you can schedule the rough-in with confidence."}]'::jsonb, '/images/products/brand-rack-a-tiers-allen-head-7-piece-driver-bit-kit.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-laser-buddy-recessed-lighting-template-for-3-4-and-6', 'RACKATIERS-BUDDYRECESSEDLIGHTINGTEMPLATE', 'Laser Buddy - Recessed Lighting Template for 3", 4" and 6"', 'residential-lighting', 'led-recessed-down-light', 0, null, false, 'Magnetically attaches to recessed light rough-in plates, aligning perfectly with your plumb laser for precise light positioning no measuring, no guesswo', 'Magnetically attaches to recessed light rough-in plates, aligning perfectly with your plumb laser for precise light positioning no measuring, no guesswork. Quick to attach, easy to remove, and highly reliable, it saves hours on jobs of any size, from single room upgrades to large-scale installations.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Laser Buddy - Recessed Lighting Te…', 'Buy the Laser Buddy - Recessed Lighting Template for 3", 4" and 6" wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Laser Buddy - Recessed Lighting Template for 3", 4" and 6" is a commercial-grade recessed LED downlight with the colour quality and glare control specifiers ask for. Genuine manufacturer product, with high CRI that makes finishes and merchandise look right. Toronto-area electrical contractors source commercial downlights from GSW because we stock project quantities and match spec sheets item for item.', '[{"q":"What does 90+ CRI mean for my project?","a":"CRI measures colour accuracy. A 90+ CRI downlight renders materials and skin tones faithfully — the standard for retail, galleries and healthcare, and a noticeable upgrade over 80 CRI economy fixtures."},{"q":"Can these dim on my existing controls?","a":"We stock versions dimmable by TRIAC, ELV and 0-10V. Send us the switch or control schedule and we will match the exact driver variant."}]'::jsonb, '/images/products/brand-rack-a-tiers-laser-buddy-recessed-lighting-template-for-3-4-and-6.webp');
