insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-efergy-125a-current-sensor', 'RACKATIERS-125ACURRENTSENSOR', 'Efergy 125A Current Sensor', 'residential-lighting', 'led-motion-sensor-light', 0, null, false, 'Additional sensor for measuring current up to 125 amperes. Works with the Elite Classic. Perfect for whole house applications where a 100 amp services is instal', 'Additional sensor for measuring current up to 125 amperes. Works with the Elite Classic. Perfect for whole house applications where a 100 amp services is installed. Split core design easily fits around wire sizes up to 1/0 without breaking connections. The EF012 can be used with the Elite Classic Kit (EF003) for a 3-Phase 125A installation. CAT II 600V A 200 Amp CT is currently in development.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Efergy 125A Current Sensor Canada', 'Buy the Efergy 125A Current Sensor wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Efergy 125A Current Sensor is a motion-activated LED security light that switches on when it matters and stays off when it does not. Genuine manufacturer product with adjustable sensing so you cover the entry, driveway or yard without nuisance trips. GSW is an electrical wholesaler supplying motion sensor lighting across the GTA with contractor pricing and counter pickup in Mississauga.', '[{"q":"Can I adjust the sensitivity and timer?","a":"Yes — the PIR range, dwell time and lux threshold are all field-adjustable, so the light only triggers at night and only when you want it to."},{"q":"Is hardwiring required?","a":"These are hardwired 120V fixtures. For areas without a nearby box, ask us about solar or plug-in alternatives when you call."}]'::jsonb, '/images/products/brand-rack-a-tiers-efergy-125a-current-sensor.webp');
