insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-ac-sensor', 'RACKATIERS-SENSOR', 'AC Sensor', 'residential-lighting', 'led-motion-sensor-light', 0, null, false, 'Prevent electrical shock with this simple tool to located dangerous defective grounds. This handheld device helps you determine the presence or absence of 50-10', 'Prevent electrical shock with this simple tool to located dangerous defective grounds. This handheld device helps you determine the presence or absence of 50-1000 Volts AC in insulated wires, wall receptacles, fuses, junction boxes, and voltage carrying electrical systems. The bright, red glow indicates AC voltage.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'AC Sensor Canada', 'Buy the AC Sensor wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The AC Sensor is a motion-activated LED security light that switches on when it matters and stays off when it does not. Genuine manufacturer product with adjustable sensing so you cover the entry, driveway or yard without nuisance trips. GSW is an electrical wholesaler supplying motion sensor lighting across the GTA with contractor pricing and counter pickup in Mississauga.', '[{"q":"Can I adjust the sensitivity and timer?","a":"Yes — the PIR range, dwell time and lux threshold are all field-adjustable, so the light only triggers at night and only when you want it to."},{"q":"Is hardwiring required?","a":"These are hardwired 120V fixtures. For areas without a nearby box, ask us about solar or plug-in alternatives when you call."}]'::jsonb, '/images/products/brand-rack-a-tiers-ac-sensor.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-ultimate-ac-sensor', 'RACKATIERS-ACSENSOR', 'Ultimate AC Sensor', 'residential-lighting', 'led-motion-sensor-light', 0, null, false, 'Prevent electrical shock with this simple tool to located dangerous defective grounds. ULTIMATE model has added audio alert feature. This handheld device helps', 'Prevent electrical shock with this simple tool to located dangerous defective grounds. ULTIMATE model has added audio alert feature. This handheld device helps you determine the presence or absence of 50-1000 Volts AC in insulated wires, wall receptacles, fuses, junction boxes, and voltage carrying electrical systems. The bright, red glow indicates AC voltage.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Ultimate AC Sensor Canada', 'Buy the Ultimate AC Sensor wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Ultimate AC Sensor is a motion-activated LED security light that switches on when it matters and stays off when it does not. Genuine manufacturer product with adjustable sensing so you cover the entry, driveway or yard without nuisance trips. GSW is an electrical wholesaler supplying motion sensor lighting across the GTA with contractor pricing and counter pickup in Mississauga.', '[{"q":"Can I adjust the sensitivity and timer?","a":"Yes — the PIR range, dwell time and lux threshold are all field-adjustable, so the light only triggers at night and only when you want it to."},{"q":"Is hardwiring required?","a":"These are hardwired 120V fixtures. For areas without a nearby box, ask us about solar or plug-in alternatives when you call."}]'::jsonb, '/images/products/brand-rack-a-tiers-ultimate-ac-sensor.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-multi-bit-step-drill-bit-rack-a', 'RACKATIERS-BITSTEPDRILLBITRACKA', 'Multi Bit - Step Drill Bit - Rack-A', 'residential-lighting', 'led-outdoor-garden-light', 0, null, false, 'Cut holes in steel, sheet metal, thin acrylic sheets, plywood, and plastic laminate with these high-quality step drill bits.', 'Cut holes in steel, sheet metal, thin acrylic sheets, plywood, and plastic laminate with these high-quality step drill bits.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Multi Bit - Step Drill Bit - Rack-A', 'Buy the Multi Bit - Step Drill Bit - Rack-A wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Multi Bit - Step Drill Bit - Rack-A is a weather-rated LED garden light built to make Ontario landscapes look their best year-round. Genuine manufacturer product in a durable housing that shrugs off rain, snow and hose spray. Landscape contractors and DIY homeowners alike buy garden lighting from GSW’s Mississauga store for the combination of wholesale pricing and in-stock depth.', '[{"q":"Low voltage or line voltage?","a":"Most landscape fixtures run on 12V AC/DC from a transformer, which is safer to bury and easier to install. Line-voltage models are available for permanent hardwired installs — call to confirm."},{"q":"Will these survive a Canadian winter?","a":"Yes — these fixtures are IP65-rated with cold-rated LEDs and drivers, tested well below typical Ontario winter temperatures."}]'::jsonb, '/images/products/brand-rack-a-tiers-multi-bit-step-drill-bit-rack-a.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-revbit-reverse-threaded-driver-bit', 'RACKATIERS-REVERSETHREADEDDRIVERBIT', 'RevBit - Reverse Threaded Driver Bit', 'commercial-lighting', 'transformer', 0, null, false, 'The RevBit takes a common item, the pilot bit, and perfects it. By being reverse threaded the RevBit eliminates any bending, breaking and mess caused by hole sa', 'The RevBit takes a common item, the pilot bit, and perfects it. By being reverse threaded the RevBit eliminates any bending, breaking and mess caused by hole saw teeth catching once your pilot bit goes through the material. HOLE SAW NOT INCLUDED. PLEASE NOTE: Limit purchases to 1 item per order', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'RevBit - Reverse Threaded Driver B…', 'Buy the RevBit - Reverse Threaded Driver Bit wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The RevBit - Reverse Threaded Driver Bit is a CSA-certified transformer for stepping service voltages down to usable distribution or control power. Genuine manufacturer product with efficient cores built for continuous duty. Electrical contractors and plant maintenance teams across Canada order transformers from GSW with lead times confirmed up front — made-to-order units are quoted honestly, not optimistically.', '[{"q":"How do I size a transformer?","a":"Sum the connected loads with a diversity factor, check inrush for motor loads, and add 20–25% growth. Send us the load schedule and we will verify the kVA rating and primary/secondary voltages before you order."},{"q":"What is the lead time on made-to-order transformers?","a":"Stock control transformers ship immediately; larger dry-type units typically run 2–4 weeks. We confirm the exact lead time on your quote so you can schedule the rough-in with confidence."}]'::jsonb, '/images/products/brand-rack-a-tiers-revbit-reverse-threaded-driver-bit.webp');
