insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-croc-s-jr-wire-strippers', 'RACKATIERS-SJRWIRESTRIPPERS', 'Croc''s Jr. - Wire Strippers', 'residential-lighting', 'led-strip-light', 0, null, false, 'Rack-A-Tiers famous wire strippers in a more compact size. Croc s Jr. has the same ergonomic glow-in-the-dark handles as the original Croc s Needle Nose', 'Rack-A-Tiers famous wire strippers in a more compact size. Croc s Jr. has the same ergonomic glow-in-the-dark handles as the original Croc s Needle Nose Wire Strippers. Protect your hands and wrists from soreness while you effortlessly strip wire sized AWG #8 #22. Croc s Jr. is designed to be as functional as possible while maintaining their portable size. These electrical wire stri', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Croc''s Jr. - Wire Strippers Canada', 'Buy the Croc''s Jr. - Wire Strippers wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Croc''s Jr. - Wire Strippers is a professional-grade LED strip light system for coves, toe-kicks, shelving and accent runs. Genuine manufacturer product on a flexible tape that cuts to length and sticks in place, with aluminum channel options for a finished architectural look. As a lighting distributor in Mississauga, GSW stocks tape, drivers and channels together so your whole run comes from one supplier.', '[{"q":"12V or 24V — which should I use?","a":"We recommend 24V for runs longer than about 5 metres to avoid voltage drop and dimming at the far end. Both are in stock; tell us the run length and we will size the driver."},{"q":"Is the strip dimmable?","a":"Yes, with a compatible dimmable driver. We can supply the matching driver and dimmer so the whole circuit dims smoothly from one switch."}]'::jsonb, '/images/products/brand-rack-a-tiers-croc-s-jr-wire-strippers.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('reno-architectural-ring-fixture', 'RENO-ARCHITECTURALRINGFIXTURE', 'Architectural Ring Fixture', 'residential-lighting', 'led-ceiling-fixture', 0, null, true, 'The Aurora s circular form defines its environment with subtle sophistication. Its shape accentuates architectural lines, softens edges, and creates a sense of', 'The Aurora s circular form defines its environment with subtle sophistication. Its shape accentuates architectural lines, softens edges, and creates a sense of balance within any space blending sculptural beauty with purposeful illumination.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Architectural Ring Fixture Canada', 'Buy the Architectural Ring Fixture wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Architectural Ring Fixture is a surface-mount LED ceiling fixture built for dependable, maintenance-free residential light. Genuine manufacturer product, with a diffuser that spreads light evenly and hides hotspots. Contractors across Mississauga, Brampton and Toronto choose GSW for ceiling fixtures because we keep depth of stock, quote real wholesale pricing, and can stage full floor packages for multi-unit jobs.', '[{"q":"Are these fixtures dimmable?","a":"Many models are dimmable to 10–20% with standard wall dimmers — check the spec row for \"dimmable\" on this model, or call us and we will confirm compatibility before you buy."},{"q":"Do you sell matching fixtures for a whole building?","a":"Yes. We regularly stage identical fixture packages for multi-unit residential jobs. Call +1 416-951-2650 with your counts and we will hold stock under one SKU."}]'::jsonb, '/images/products/brand-reno-architectural-ring-fixture.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('reno-digital-addressable-lighting-interface-dali-led-retrofit-sol', 'RENO-DIGITALADDRESSABLELIGHTINGINTERFACE', 'Digital Addressable Lighting Interface (DALI) LED Retrofit Solution', 'commercial-lighting', 'led-retrofit-corn-light', 0, null, false, 'With the phasing out of fluorescent lamps in North America, many building operators are looking to convert existing DALI system-controlled fluorescent installat', 'With the phasing out of fluorescent lamps in North America, many building operators are looking to convert existing DALI system-controlled fluorescent installations to LED technology. Our Retrofit Solution is the answer.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Digital Addressable Lighting Inter…', 'Buy the Digital Addressable Lighting Interface (DALI) LED Retrofit Solution wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30…', 'The Digital Addressable Lighting Interface (DALI) LED Retrofit Solution is an LED corn light that retrofits HID lamps — metal halide and high-pressure sodium — without replacing the fixture. Genuine manufacturer product on a mogul base that screws straight into the existing socket after a ballast bypass. Contractors retrofitting post tops, wall packs and high bays buy corn lights from GSW at wholesale pricing with same-day GTA pickup.', '[{"q":"Do I remove the ballast?","a":"Yes — corn lamps operate on line voltage and require a ballast bypass (direct wire). It is a straightforward change our customers do every day; if you are unsure, any licensed electrician can handle it quickly."},{"q":"What HID wattage does this replace?","a":"Genuine manufacturer product typically replaces a 400W HID lamp at roughly half the energy draw and many times the rated life."}]'::jsonb, '/images/products/brand-reno-digital-addressable-lighting-interface-dali-led-retrofit-sol.webp');
