insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('reno-reno-hbu-cover-g3', 'RENO-RENOHBUCOVERG3', 'RENO-HBU-COVER-G3', 'residential-lighting', 'led-strip-light', 0, null, false, 'PC Prismatic Reflector Lens for G3 R2 Prime UFO HIGHBAY', 'PC Prismatic Reflector Lens for G3 R2 Prime UFO HIGHBAY', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'RENO-HBU-COVER-G3 Canada', 'Buy the RENO-HBU-COVER-G3 wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The RENO-HBU-COVER-G3 is a professional-grade LED strip light system for coves, toe-kicks, shelving and accent runs. Genuine manufacturer product on a flexible tape that cuts to length and sticks in place, with aluminum channel options for a finished architectural look. As a lighting distributor in Mississauga, GSW stocks tape, drivers and channels together so your whole run comes from one supplier.', '[{"q":"12V or 24V — which should I use?","a":"We recommend 24V for runs longer than about 5 metres to avoid voltage drop and dimming at the far end. Both are in stock; tell us the run length and we will size the driver."},{"q":"Is the strip dimmable?","a":"Yes, with a compatible dimmable driver. We can supply the matching driver and dimmer so the whole circuit dims smoothly from one switch."}]'::jsonb, '/images/products/brand-reno-reno-hbu-cover-g3.webp');
