insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-6-quot-commercial-led-downlight-30w-5', 'VOTATEC-6QUOTCOMMERCIALLEDDOWNLI', '6&quot; Commercial LED Downlight, 30W 5', 'residential-lighting', 'led-recessed-down-light', 0, null, false, '6&quot; commercial LED downlight, 12W to 30W selectable, 125Lm/W, 5-CCT (2700K to 5000K), AC120-347V, wet-location rated, CRI &gt;90. Request a quote.', '6&quot; commercial LED downlight, 12W to 30W selectable, 125Lm/W, 5-CCT (2700K to 5000K), AC120-347V, wet-location rated, CRI &gt;90. Request a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '6&quot; Commercial LED Downlight,…', 'Buy the 6&quot; Commercial LED Downlight, 30W 5 wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The 6&quot; Commercial LED Downlight, 30W 5 is a commercial-grade recessed LED downlight with the colour quality and glare control specifiers ask for. Genuine manufacturer product, with high CRI that makes finishes and merchandise look right. Toronto-area electrical contractors source commercial downlights from GSW because we stock project quantities and match spec sheets item for item.', '[{"q":"What does 90+ CRI mean for my project?","a":"CRI measures colour accuracy. A 90+ CRI downlight renders materials and skin tones faithfully — the standard for retail, galleries and healthcare, and a noticeable upgrade over 80 CRI economy fixtures."},{"q":"Can these dim on my existing controls?","a":"We stock versions dimmable by TRIAC, ELV and 0-10V. Send us the switch or control schedule and we will match the exact driver variant."}]'::jsonb, '/images/products/brand-votatec-6-quot-commercial-led-downlight-30w-5.webp');
