insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-gps-lightlock', 'RACKATIERS-ATIERSGPSLIGHTLOCK', 'GPS LightLock', 'residential-lighting', 'led-ceiling-fixture', 0, null, false, 'Features: Installs in under a minute! The world&#x27;s only fully automatic astronomical timer. Switches lights dusk-to-dawn anywhere in the world. Plug &amp; p', 'Features: Installs in under a minute! The world&#x27;s only fully automatic astronomical timer. Switches lights dusk-to-dawn anywhere in the world. Plug &amp; play. Never needs programming. Self recovers from power outages. Direct replacement for twist-lock photocells. Load rating 1800VA. Listed to UL916. 15 Year Warranty. Made in USA', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'GPS LightLock Canada', 'Buy the GPS LightLock wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The GPS LightLock is a surface-mount LED ceiling fixture built for dependable, maintenance-free residential light. Genuine manufacturer product, with a diffuser that spreads light evenly and hides hotspots. Contractors across Mississauga, Brampton and Toronto choose GSW for ceiling fixtures because we keep depth of stock, quote real wholesale pricing, and can stage full floor packages for multi-unit jobs.', '[{"q":"Are these fixtures dimmable?","a":"Many models are dimmable to 10–20% with standard wall dimmers — check the spec row for \"dimmable\" on this model, or call us and we will confirm compatibility before you buy."},{"q":"Do you sell matching fixtures for a whole building?","a":"Yes. We regularly stage identical fixture packages for multi-unit residential jobs. Call +1 416-951-2650 with your counts and we will hold stock under one SKU."}]'::jsonb, '/images/products/brand-rack-a-tiers-gps-lightlock.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-panel-buddy-knockout-kit', 'RACKATIERS-ATIERSPANELBUDDYKNOCKOUT', 'Panel Buddy Knockout Kit', 'commercial-lighting', 'led-flat-panel', 0, null, false, 'Tired of trying to remove knockouts? Remove knockouts in half the time, with half the effort and prevents damage to the drywall.', 'Tired of trying to remove knockouts? Remove knockouts in half the time, with half the effort and prevents damage to the drywall.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Panel Buddy Knockout Kit Canada', 'Buy the Panel Buddy Knockout Kit wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Panel Buddy Knockout Kit is a commercial-grade LED flat panel for offices, schools, clinics and retail back-of-house spaces. Genuine manufacturer product with a uniform, glare-free lens that meets modern workplace standards. GSW supplies commercial LED lighting wholesale to Toronto-area contractors, with DLC-listed models that qualify for utility incentives and stock ready for pickup or flat-rate shipping.', '[{"q":"Is this panel DLC listed?","a":"Yes — our commercial panels carry DLC or DLC Premium listing, which qualifies many projects for Hydro One and Toronto Hydro rebate programs. We can provide the DLC ID on request."},{"q":"2x2 or 2x4 — which do I need?","a":"Match the existing grid: most Toronto commercial ceilings are 2x2 or 2x4 T-bar. Retrofit kits are also available if you are converting from parabolic troffers — call us with the fixture count."}]'::jsonb, '/images/products/brand-rack-a-tiers-panel-buddy-knockout-kit.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-multi-bit', 'RACKATIERS-ATIERSMULTIBIT', 'Multi Bit', 'residential-lighting', 'led-outdoor-garden-light', 0, null, false, 'Cut holes in steel, sheet metal, thin acrylic sheets, plywood, and plastic laminate with these high-quality step drill bits.', 'Cut holes in steel, sheet metal, thin acrylic sheets, plywood, and plastic laminate with these high-quality step drill bits.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Multi Bit Canada', 'Buy the Multi Bit wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Multi Bit is a weather-rated LED garden light built to make Ontario landscapes look their best year-round. Genuine manufacturer product in a durable housing that shrugs off rain, snow and hose spray. Landscape contractors and DIY homeowners alike buy garden lighting from GSW’s Mississauga store for the combination of wholesale pricing and in-stock depth.', '[{"q":"Low voltage or line voltage?","a":"Most landscape fixtures run on 12V AC/DC from a transformer, which is safer to bury and easier to install. Line-voltage models are available for permanent hardwired installs — call to confirm."},{"q":"Will these survive a Canadian winter?","a":"Yes — these fixtures are IP65-rated with cold-rated LEDs and drivers, tested well below typical Ontario winter temperatures."}]'::jsonb, '/images/products/brand-rack-a-tiers-multi-bit.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-revbit', 'RACKATIERS-ATIERSREVBIT', 'RevBit', 'commercial-lighting', 'transformer', 0, null, false, 'Features: Reverse threaded pilot bit for a soft landing once the pilot bit breaches the work surface. 4&quot; in length. Made from high speed steel. Works with', 'Features: Reverse threaded pilot bit for a soft landing once the pilot bit breaches the work surface. 4&quot; in length. Made from high speed steel. Works with any standard hole saw. Will not tear sheet-rock, or finished wall surface. Preserves the hole saw teeth, for the entire life of the tool. Made in the USA.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'RevBit Canada', 'Buy the RevBit wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The RevBit is a CSA-certified transformer for stepping service voltages down to usable distribution or control power. Genuine manufacturer product with efficient cores built for continuous duty. Electrical contractors and plant maintenance teams across Canada order transformers from GSW with lead times confirmed up front — made-to-order units are quoted honestly, not optimistically.', '[{"q":"How do I size a transformer?","a":"Sum the connected loads with a diversity factor, check inrush for motor loads, and add 20–25% growth. Send us the load schedule and we will verify the kVA rating and primary/secondary voltages before you order."},{"q":"What is the lead time on made-to-order transformers?","a":"Stock control transformers ship immediately; larger dry-type units typically run 2–4 weeks. We confirm the exact lead time on your quote so you can schedule the rough-in with confidence."}]'::jsonb, '/images/products/brand-rack-a-tiers-revbit.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-impact-driver-bits', 'RACKATIERS-ATIERSIMPACTDRIVERBITS', 'Impact Driver Bits', 'commercial-lighting', 'transformer', 0, null, false, 'These impact rated driver bits are made from a stronger steel to withstand the added stress. Available in 1 , 2 , 4 and 6 and featuring the same colour coding', 'These impact rated driver bits are made from a stronger steel to withstand the added stress. Available in 1 , 2 , 4 and 6 and featuring the same colour coding as [ ]', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Impact Driver Bits Canada', 'Buy the Impact Driver Bits wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Impact Driver Bits is a CSA-certified transformer for stepping service voltages down to usable distribution or control power. Genuine manufacturer product with efficient cores built for continuous duty. Electrical contractors and plant maintenance teams across Canada order transformers from GSW with lead times confirmed up front — made-to-order units are quoted honestly, not optimistically.', '[{"q":"How do I size a transformer?","a":"Sum the connected loads with a diversity factor, check inrush for motor loads, and add 20–25% growth. Send us the load schedule and we will verify the kVA rating and primary/secondary voltages before you order."},{"q":"What is the lead time on made-to-order transformers?","a":"Stock control transformers ship immediately; larger dry-type units typically run 2–4 weeks. We confirm the exact lead time on your quote so you can schedule the rough-in with confidence."}]'::jsonb, '/images/products/brand-rack-a-tiers-impact-driver-bits.webp');
