insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-ez-bulb-kit', 'RACKATIERS-ATIERSEZBULBKIT', 'EZ Bulb Kit', 'commercial-lighting', 'led-retrofit-corn-light', 0, null, false, 'The EZ Bulb makes it effortless to change and replace par LED lamps with simple, easy to use lamp changers that fit on any universal extension pole. The EZ Bulb', 'The EZ Bulb makes it effortless to change and replace par LED lamps with simple, easy to use lamp changers that fit on any universal extension pole. The EZ Bulb [ ]', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'EZ Bulb Kit Canada', 'Buy the EZ Bulb Kit wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The EZ Bulb Kit is an LED corn light that retrofits HID lamps — metal halide and high-pressure sodium — without replacing the fixture. Genuine manufacturer product on a mogul base that screws straight into the existing socket after a ballast bypass. Contractors retrofitting post tops, wall packs and high bays buy corn lights from GSW at wholesale pricing with same-day GTA pickup.', '[{"q":"Do I remove the ballast?","a":"Yes — corn lamps operate on line voltage and require a ballast bypass (direct wire). It is a straightforward change our customers do every day; if you are unsure, any licensed electrician can handle it quickly."},{"q":"What HID wattage does this replace?","a":"Genuine manufacturer product typically replaces a 400W HID lamp at roughly half the energy draw and many times the rated life."}]'::jsonb, '/images/products/brand-rack-a-tiers-ez-bulb-kit.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-robertson-square-screw-drivers', 'RACKATIERS-ATIERSROBERTSONSQUARESCR', 'Robertson Square Screw Drivers', 'commercial-lighting', 'transformer', 0, null, false, 'Features: Great Quality. Great Fit. Most Torque. Best Grip.', 'Features: Great Quality. Great Fit. Most Torque. Best Grip.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Robertson Square Screw Drivers', 'Buy the Robertson Square Screw Drivers wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Robertson Square Screw Drivers is a CSA-certified transformer for stepping service voltages down to usable distribution or control power. Genuine manufacturer product with efficient cores built for continuous duty. Electrical contractors and plant maintenance teams across Canada order transformers from GSW with lead times confirmed up front — made-to-order units are quoted honestly, not optimistically.', '[{"q":"How do I size a transformer?","a":"Sum the connected loads with a diversity factor, check inrush for motor loads, and add 20–25% growth. Send us the load schedule and we will verify the kVA rating and primary/secondary voltages before you order."},{"q":"What is the lead time on made-to-order transformers?","a":"Stock control transformers ship immediately; larger dry-type units typically run 2–4 weeks. We confirm the exact lead time on your quote so you can schedule the rough-in with confidence."}]'::jsonb, '/images/products/brand-rack-a-tiers-robertson-square-screw-drivers.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('etlin-flh5s-2', 'ETLIN-FLH5S2', 'FLH5S', 'commercial-lighting', 'led-flood-light', 0, null, false, 'Square and Round Pole Mount for FLH5S LED Flood Light', 'Square and Round Pole Mount for FLH5S LED Flood Light', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'FLH5S Canada', 'Buy the FLH5S wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The FLH5S is a high-output LED flood light engineered for large areas — parking lots, yards, facades and sports surfaces. Genuine manufacturer product with precision optics that put light on the target, not the neighbours. GSW is a Canadian wholesale LED lighting supplier, so flood lights ship flat-rate across the country and are always available for pickup at our Mississauga counter.', '[{"q":"How do I choose wattage for a parking lot?","a":"As a rule of thumb, 100W–150W LED replaces a 400W metal halide shoebox or flood. Tell us the pole height and spacing and we will run a quick layout to confirm foot-candles before you commit."},{"q":"Are these lights dimmable or motion-controllable?","a":"Most models accept 0-10V dimming and pair with motion sensors or photocells for after-hours energy savings. We stock compatible controls."}]'::jsonb, '/images/products/brand-etlin-flh5s-2.webp');
