insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('etlin-rtbp5smk-2', 'ETLIN-RTBP5SMK2', 'RTBP5SMK', 'commercial-lighting', 'led-flat-panel', 0, null, false, 'Surface Mount Kit for RTBP5 2 Ft X 4 Ft LED Flat Panel (BACK LIT PANELS REQUIRE BACK LIT SURFACE MOUNT KITS)', 'Surface Mount Kit for RTBP5 2 Ft X 4 Ft LED Flat Panel (BACK LIT PANELS REQUIRE BACK LIT SURFACE MOUNT KITS)', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'RTBP5SMK Canada', 'Buy the RTBP5SMK wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The RTBP5SMK is a commercial-grade LED flat panel for offices, schools, clinics and retail back-of-house spaces. Genuine manufacturer product with a uniform, glare-free lens that meets modern workplace standards. GSW supplies commercial LED lighting wholesale to Toronto-area contractors, with DLC-listed models that qualify for utility incentives and stock ready for pickup or flat-rate shipping.', '[{"q":"Is this panel DLC listed?","a":"Yes — our commercial panels carry DLC or DLC Premium listing, which qualifies many projects for Hydro One and Toronto Hydro rebate programs. We can provide the DLC ID on request."},{"q":"2x2 or 2x4 — which do I need?","a":"Match the existing grid: most Toronto commercial ceilings are 2x2 or 2x4 T-bar. Retrofit kits are also available if you are converting from parabolic troffers — call us with the fixture count."}]'::jsonb, '/images/products/brand-etlin-rtbp5smk-2.webp');
