insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('votatec-4-quot-commercial-led-downlight', 'VOTATEC-4QUOTCOMMERCIALLEDDOWNLI', '4&quot; Commercial LED Downlight', 'residential-lighting', 'led-recessed-down-light', 0, null, false, '4&quot; recessed commercial LED downlight, 5-way CCT selectable and adjustable power. For offices, retail, and institutional projects. Request a quote.', '4&quot; recessed commercial LED downlight, 5-way CCT selectable and adjustable power. For offices, retail, and institutional projects. Request a quote.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', '4&quot; Commercial LED Downlight', 'Buy the 4&quot; Commercial LED Downlight wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The 4&quot; Commercial LED Downlight is a commercial-grade recessed LED downlight with the colour quality and glare control specifiers ask for. Genuine manufacturer product, with high CRI that makes finishes and merchandise look right. Toronto-area electrical contractors source commercial downlights from GSW because we stock project quantities and match spec sheets item for item.', '[{"q":"What does 90+ CRI mean for my project?","a":"CRI measures colour accuracy. A 90+ CRI downlight renders materials and skin tones faithfully — the standard for retail, galleries and healthcare, and a noticeable upgrade over 80 CRI economy fixtures."},{"q":"Can these dim on my existing controls?","a":"We stock versions dimmable by TRIAC, ELV and 0-10V. Send us the switch or control schedule and we will match the exact driver variant."}]'::jsonb, '/images/products/brand-votatec-4-quot-commercial-led-downlight.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('canolight-cl-23', 'CANOLIGHT-CL23', 'CL', 'residential-lighting', 'led-strip-light', 0, null, false, 'LL1 Up &amp; Down LED Linear Light Accessory - PC Cover 25ft/roll Dimensions available in catalogue sheet', 'LL1 Up &amp; Down LED Linear Light Accessory - PC Cover 25ft/roll Dimensions available in catalogue sheet', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'CL Canada', 'Buy the CL wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The CL is a professional-grade LED strip light system for coves, toe-kicks, shelving and accent runs. Genuine manufacturer product on a flexible tape that cuts to length and sticks in place, with aluminum channel options for a finished architectural look. As a lighting distributor in Mississauga, GSW stocks tape, drivers and channels together so your whole run comes from one supplier.', '[{"q":"12V or 24V — which should I use?","a":"We recommend 24V for runs longer than about 5 metres to avoid voltage drop and dimming at the far end. Both are in stock; tell us the run length and we will size the driver."},{"q":"Is the strip dimmable?","a":"Yes, with a compatible dimmable driver. We can supply the matching driver and dimmer so the whole circuit dims smoothly from one switch."}]'::jsonb, '/images/products/brand-canolight-cl-23.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('canolight-cl-24', 'CANOLIGHT-CL24', 'CL', 'residential-lighting', 'led-ceiling-fixture', 0, null, false, '2ft Up &amp; Down LED Linear Light 15/20/25W Adjustable Power 130lm/W Available in Black and White body 3CCT (3000K,3500K,4000K) 120-347V Input Voltage Bridgelu', '2ft Up &amp; Down LED Linear Light 15/20/25W Adjustable Power 130lm/W Available in Black and White body 3CCT (3000K,3500K,4000K) 120-347V Input Voltage Bridgelux LED Chip Flicker free isolated driver Maximum Connection at 25W: 110V: 16 PCS in series 277V: 40 PCS in series 347V: 50 PCS in series', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'CL Canada', 'Buy the CL wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The CL is a surface-mount LED ceiling fixture built for dependable, maintenance-free residential light. Genuine manufacturer product, with a diffuser that spreads light evenly and hides hotspots. Contractors across Mississauga, Brampton and Toronto choose GSW for ceiling fixtures because we keep depth of stock, quote real wholesale pricing, and can stage full floor packages for multi-unit jobs.', '[{"q":"Are these fixtures dimmable?","a":"Many models are dimmable to 10–20% with standard wall dimmers — check the spec row for \"dimmable\" on this model, or call us and we will confirm compatibility before you buy."},{"q":"Do you sell matching fixtures for a whole building?","a":"Yes. We regularly stage identical fixture packages for multi-unit residential jobs. Call +1 416-951-2650 with your counts and we will hold stock under one SKU."}]'::jsonb, '/images/products/brand-canolight-cl-24.webp');
