insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-allen-head-1-2-quot-x-6-quot-driver-bit', 'RACKATIERS-ATIERSALLENHEAD12QUOTX6Q', 'Allen Head 1/2&quot; x 6&quot; Driver Bit', 'commercial-lighting', 'transformer', 0, null, false, 'Features: Industrial grade bits. Extremely durable. 1/4&quot; hex shank. Quick connect design. Hard to find 6&quot; length.', 'Features: Industrial grade bits. Extremely durable. 1/4&quot; hex shank. Quick connect design. Hard to find 6&quot; length.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Allen Head 1/2&quot; x 6&quot; Dri…', 'Buy the Allen Head 1/2&quot; x 6&quot; Driver Bit wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Allen Head 1/2&quot; x 6&quot; Driver Bit is a CSA-certified transformer for stepping service voltages down to usable distribution or control power. Genuine manufacturer product with efficient cores built for continuous duty. Electrical contractors and plant maintenance teams across Canada order transformers from GSW with lead times confirmed up front — made-to-order units are quoted honestly, not optimistically.', '[{"q":"How do I size a transformer?","a":"Sum the connected loads with a diversity factor, check inrush for motor loads, and add 20–25% growth. Send us the load schedule and we will verify the kVA rating and primary/secondary voltages before you order."},{"q":"What is the lead time on made-to-order transformers?","a":"Stock control transformers ship immediately; larger dry-type units typically run 2–4 weeks. We confirm the exact lead time on your quote so you can schedule the rough-in with confidence."}]'::jsonb, '/images/products/brand-rack-a-tiers-allen-head-1-2-quot-x-6-quot-driver-bit.webp');
