insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-slyder', 'RACKATIERS-ATIERSSLYDER', 'Slyder', 'commercial-lighting', 'transformer', 0, null, false, 'The only two-in-one driver bit and wire nut spinner for electricians - Made by Rack-A-Tiers.', 'The only two-in-one driver bit and wire nut spinner for electricians - Made by Rack-A-Tiers.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Slyder Canada', 'Buy the Slyder wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Slyder is a CSA-certified transformer for stepping service voltages down to usable distribution or control power. Genuine manufacturer product with efficient cores built for continuous duty. Electrical contractors and plant maintenance teams across Canada order transformers from GSW with lead times confirmed up front — made-to-order units are quoted honestly, not optimistically.', '[{"q":"How do I size a transformer?","a":"Sum the connected loads with a diversity factor, check inrush for motor loads, and add 20–25% growth. Send us the load schedule and we will verify the kVA rating and primary/secondary voltages before you order."},{"q":"What is the lead time on made-to-order transformers?","a":"Stock control transformers ship immediately; larger dry-type units typically run 2–4 weeks. We confirm the exact lead time on your quote so you can schedule the rough-in with confidence."}]'::jsonb, '/images/products/brand-rack-a-tiers-slyder.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-malco-c', 'RACKATIERS-ATIERSMALCOC', 'Malco C', 'commercial-lighting', 'transformer', 0, null, false, 'Malco s popular C-RHEX Cleanable, Reversible Magnetic Hex Drivers are made for ultimate flexibility and productivity. Instantly change between 3/8&quot;', 'Malco s popular C-RHEX Cleanable, Reversible Magnetic Hex Drivers are made for ultimate flexibility and productivity. Instantly change between 3/8&quot;', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Malco C Canada', 'Buy the Malco C wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Malco C is a CSA-certified transformer for stepping service voltages down to usable distribution or control power. Genuine manufacturer product with efficient cores built for continuous duty. Electrical contractors and plant maintenance teams across Canada order transformers from GSW with lead times confirmed up front — made-to-order units are quoted honestly, not optimistically.', '[{"q":"How do I size a transformer?","a":"Sum the connected loads with a diversity factor, check inrush for motor loads, and add 20–25% growth. Send us the load schedule and we will verify the kVA rating and primary/secondary voltages before you order."},{"q":"What is the lead time on made-to-order transformers?","a":"Stock control transformers ship immediately; larger dry-type units typically run 2–4 weeks. We confirm the exact lead time on your quote so you can schedule the rough-in with confidence."}]'::jsonb, '/images/products/brand-rack-a-tiers-malco-c.webp');
