insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-malco-c-2', 'RACKATIERS-ATIERSMALCOC2', 'Malco C', 'commercial-lighting', 'transformer', 0, null, false, 'Malco s popular C-RHEX Cleanable, Reversible Magnetic Hex Drivers are made for ultimate flexibility and productivity. Instantly change between 1/4&quot;', 'Malco s popular C-RHEX Cleanable, Reversible Magnetic Hex Drivers are made for ultimate flexibility and productivity. Instantly change between 1/4&quot;', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Malco C Canada', 'Buy the Malco C wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Malco C is a CSA-certified transformer for stepping service voltages down to usable distribution or control power. Genuine manufacturer product with efficient cores built for continuous duty. Electrical contractors and plant maintenance teams across Canada order transformers from GSW with lead times confirmed up front — made-to-order units are quoted honestly, not optimistically.', '[{"q":"How do I size a transformer?","a":"Sum the connected loads with a diversity factor, check inrush for motor loads, and add 20–25% growth. Send us the load schedule and we will verify the kVA rating and primary/secondary voltages before you order."},{"q":"What is the lead time on made-to-order transformers?","a":"Stock control transformers ship immediately; larger dry-type units typically run 2–4 weeks. We confirm the exact lead time on your quote so you can schedule the rough-in with confidence."}]'::jsonb, '/images/products/brand-rack-a-tiers-malco-c-2.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-copper-wire-stripper-jr-parts', 'RACKATIERS-ATIERSCOPPERWIRESTRIPPER', 'Copper Wire Stripper Jr. Parts', 'residential-lighting', 'led-strip-light', 0, null, false, 'Please note: These products are special order and may take 2-3 weeks for delivery.', 'Please note: These products are special order and may take 2-3 weeks for delivery.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Copper Wire Stripper Jr. Parts', 'Buy the Copper Wire Stripper Jr. Parts wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Copper Wire Stripper Jr. Parts is a professional-grade LED strip light system for coves, toe-kicks, shelving and accent runs. Genuine manufacturer product on a flexible tape that cuts to length and sticks in place, with aluminum channel options for a finished architectural look. As a lighting distributor in Mississauga, GSW stocks tape, drivers and channels together so your whole run comes from one supplier.', '[{"q":"12V or 24V — which should I use?","a":"We recommend 24V for runs longer than about 5 metres to avoid voltage drop and dimming at the far end. Both are in stock; tell us the run length and we will size the driver."},{"q":"Is the strip dimmable?","a":"Yes, with a compatible dimmable driver. We can supply the matching driver and dimmer so the whole circuit dims smoothly from one switch."}]'::jsonb, '/images/products/brand-rack-a-tiers-copper-wire-stripper-jr-parts.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-gps-lightlock-wire', 'RACKATIERS-ATIERSGPSLIGHTLOCKWIRE', 'GPS LightLock Wire', 'residential-lighting', 'led-ceiling-fixture', 0, null, false, 'Features: The most popular model available. Includes twist-lock astronomical timer plus wire-in twist-lock socket with 1/2&quot; standard female thread. Direct', 'Features: The most popular model available. Includes twist-lock astronomical timer plus wire-in twist-lock socket with 1/2&quot; standard female thread. Direct replacement for all wire-in photocells and programmable timers. Load rating 1800VA. Listed to UL916. 15 Year Warranty. Made in USA', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'GPS LightLock Wire Canada', 'Buy the GPS LightLock Wire wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The GPS LightLock Wire is a surface-mount LED ceiling fixture built for dependable, maintenance-free residential light. Genuine manufacturer product, with a diffuser that spreads light evenly and hides hotspots. Contractors across Mississauga, Brampton and Toronto choose GSW for ceiling fixtures because we keep depth of stock, quote real wholesale pricing, and can stage full floor packages for multi-unit jobs.', '[{"q":"Are these fixtures dimmable?","a":"Many models are dimmable to 10–20% with standard wall dimmers — check the spec row for \"dimmable\" on this model, or call us and we will confirm compatibility before you buy."},{"q":"Do you sell matching fixtures for a whole building?","a":"Yes. We regularly stage identical fixture packages for multi-unit residential jobs. Call +1 416-951-2650 with your counts and we will hold stock under one SKU."}]'::jsonb, '/images/products/brand-rack-a-tiers-gps-lightlock-wire.webp');
