');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('rack-a-tiers-extendo-nut-driver', 'RACKATIERS-ATIERSEXTENDONUTDRIVER', 'Extendo Nut Driver', 'commercial-lighting', 'transformer', 0, null, false, 'Features: Kit includes: 7/16&quot;, 9/16&quot;, and drill attachment. 7/16&quot; nut driver attachment for 1/4&quot; threaded rod. 9/16&quot; nut driver attachm', 'Features: Kit includes: 7/16&quot;, 9/16&quot;, and drill attachment. 7/16&quot; nut driver attachment for 1/4&quot; threaded rod. 9/16&quot; nut driver attachment for 3/8&quot; threaded rod. No need to buy multiple hollow shank nut drivers. Drill attachment designed for 1/4&quot; chuck, will fit quick change drills. Adaptable to any length nut driver needed.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'Extendo Nut Driver Canada', 'Buy the Extendo Nut Driver wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The Extendo Nut Driver is a CSA-certified transformer for stepping service voltages down to usable distribution or control power. Genuine manufacturer product with efficient cores built for continuous duty. Electrical contractors and plant maintenance teams across Canada order transformers from GSW with lead times confirmed up front — made-to-order units are quoted honestly, not optimistically.', '[{"q":"How do I size a transformer?","a":"Sum the connected loads with a diversity factor, check inrush for motor loads, and add 20–25% growth. Send us the load schedule and we will verify the kVA rating and primary/secondary voltages before you order."},{"q":"What is the lead time on made-to-order transformers?","a":"Stock control transformers ship immediately; larger dry-type units typically run 2–4 weeks. We confirm the exact lead time on your quote so you can schedule the rough-in with confidence."}]'::jsonb, '/images/products/brand-rack-a-tiers-extendo-nut-driver.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('etlin-rtp4bxm', 'ETLIN-RTP4BXM', 'RTP4BXM', 'commercial-lighting', 'led-flat-panel', 0, null, false, 'Surface Mount Kit for RTP4 Series 2 x 4 LED Flat Panel', 'Surface Mount Kit for RTP4 Series 2 x 4 LED Flat Panel', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'RTP4BXM Canada', 'Buy the RTP4BXM wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The RTP4BXM is a commercial-grade LED flat panel for offices, schools, clinics and retail back-of-house spaces. Genuine manufacturer product with a uniform, glare-free lens that meets modern workplace standards. GSW supplies commercial LED lighting wholesale to Toronto-area contractors, with DLC-listed models that qualify for utility incentives and stock ready for pickup or flat-rate shipping.', '[{"q":"Is this panel DLC listed?","a":"Yes — our commercial panels carry DLC or DLC Premium listing, which qualifies many projects for Hydro One and Toronto Hydro rebate programs. We can provide the DLC ID on request."},{"q":"2x2 or 2x4 — which do I need?","a":"Match the existing grid: most Toronto commercial ceilings are 2x2 or 2x4 T-bar. Retrofit kits are also available if you are converting from parabolic troffers — call us with the fixture count."}]'::jsonb, '/images/products/brand-etlin-rtp4bxm.webp');
