insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('canolight-art', 'CANOLIGHT-ART', 'ART', 'residential-lighting', 'led-ceiling-fixture', 0, null, false, 'Smart Permanent Exterior String Light Professional-grade smart string lights for year-round outdoor beauty. Artlight&#039;s Smart Permanent Exterior String Ligh', 'Smart Permanent Exterior String Light Professional-grade smart string lights for year-round outdoor beauty. Artlight&#039;s Smart Permanent Exterior String Lights deliver professional-level outdoor illumination with individually addressable RGBICW LEDs. Built to withstand all weather conditions, these smart string lights are perfect for patios, gardens, restaurants, rooftops, and other commercial', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'ART Canada', 'Buy the ART wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The ART is a surface-mount LED ceiling fixture built for dependable, maintenance-free residential light. Genuine manufacturer product, with a diffuser that spreads light evenly and hides hotspots. Contractors across Mississauga, Brampton and Toronto choose GSW for ceiling fixtures because we keep depth of stock, quote real wholesale pricing, and can stage full floor packages for multi-unit jobs.', '[{"q":"Are these fixtures dimmable?","a":"Many models are dimmable to 10–20% with standard wall dimmers — check the spec row for \"dimmable\" on this model, or call us and we will confirm compatibility before you buy."},{"q":"Do you sell matching fixtures for a whole building?","a":"Yes. We regularly stage identical fixture packages for multi-unit residential jobs. Call +1 416-951-2650 with your counts and we will hold stock under one SKU."}]'::jsonb, '/images/products/brand-canolight-art.webp');
insert into public.products (slug, sku, name, collection, category, price, "compareAt", featured, short, description, specs, stock, meta_title, meta_description, long_description, faqs, image_url) values ('canolight-cl-2', 'CANOLIGHT-CL2', 'CL', 'residential-lighting', 'led-ceiling-fixture', 0, null, false, 'Wall Washer SMD LED Strip Light - RGBW 24W/m Power 24VDC Input 28 LED/m 570lm White 30 Beam Angle IP67 Cutting Size: 250mm (7 LEDs) Includes 15pcs of clips, 4p', 'Wall Washer SMD LED Strip Light - RGBW 24W/m Power 24VDC Input 28 LED/m 570lm White 30 Beam Angle IP67 Cutting Size: 250mm (7 LEDs) Includes 15pcs of clips, 4pcs of end caps, and 4pcs of end caps with hole.', '["Genuine manufacturer product","Distributed by Green Solar World Inc.","Call for wholesale pricing"]'::jsonb, 'in-stock', 'CL Canada', 'Buy the CL wholesale in Canada. Genuine manufacturer product — cULus/DLC certified, flat $30 shipping.', 'The CL is a surface-mount LED ceiling fixture built for dependable, maintenance-free residential light. Genuine manufacturer product, with a diffuser that spreads light evenly and hides hotspots. Contractors across Mississauga, Brampton and Toronto choose GSW for ceiling fixtures because we keep depth of stock, quote real wholesale pricing, and can stage full floor packages for multi-unit jobs.', '[{"q":"Are these fixtures dimmable?","a":"Many models are dimmable to 10–20% with standard wall dimmers — check the spec row for \"dimmable\" on this model, or call us and we will confirm compatibility before you buy."},{"q":"Do you sell matching fixtures for a whole building?","a":"Yes. We regularly stage identical fixture packages for multi-unit residential jobs. Call +1 416-951-2650 with your counts and we will hold stock under one SKU."}]'::jsonb, '/images/products/brand-canolight-cl-2.webp');
