insert into public.reviews (author_name, rating, text, source, is_approved) values ('Moe R.', 5, 'Amazing service, great product also great price, highly recommended', 'google', true);
insert into public.reviews (author_name, rating, text, source, is_approved) values ('Cindy L.', 5, 'Great service and very reliable. He''s always helpful, gives honest advice, and usually has the materials I need. Easy to deal with and a pleasure to buy from each time.', 'google', true);
insert into public.reviews (author_name, rating, text, source, is_approved) values ('James T.', 5, 'I had an amazing experience at Green Solar World Inc! From the moment I walked in, the staff was friendly and helpful. Shahab made the whole process smooth, ensuring I felt comfortable throughout. The customer service was top-notch, and I’ll be returning!', 'google', true);
insert into public.reviews (author_name, rating, text, source, is_approved) values ('Amir K.', 5, 'I have relied on Green Solar Electrical as my primary electrical supplier for over 15 years, and they have consistently exceeded my expectations. Incredible variety of LED lighting products at very reasonable and competitive prices — highest possible recommendation.', 'google', true);
insert into public.reviews (author_name, rating, text, source, is_approved) values ('David P.', 5, 'As a contractor, I’ve dealt with many suppliers over the years, and Green Solar World Inc truly stands out. Their prices are very competitive, and their service and business ethics are excellent. The owner is very knowledgeable and always solution-oriented.', 'google', true);
